    async fn prepare_realtime_user_content_blob(
        &self,
        event: &meerkat_core::RealtimeTranscriptEvent,
    ) -> Result<Option<PreparedRealtimeUserContentBlob>, SessionError> {
        let meerkat_core::RealtimeTranscriptEvent::UserContentFinal {
            idempotency_key,
            item_id,
            previous_item_id,
            content_index,
            content,
        } = event
        else {
            return Ok(None);
        };
        let [meerkat_core::types::ContentBlock::Image { media_type, data }] = content.as_slice()
        else {
            return Err(realtime_user_content_blob_error(
                "realtime user-content blob ingress must contain exactly one image",
                "invalid content shape",
            ));
        };
        let (verified, inline_data) = match data {
            meerkat_core::types::ImageData::Inline { data } => (
                meerkat_core::validate_image_blob_payload(
                    media_type,
                    data,
                    meerkat_core::live_adapter::MAX_LIVE_IMAGE_BYTES,
                )
                .map_err(|error| {
                    realtime_user_content_blob_error(
                        "realtime inline image failed bounded integrity validation",
                        error,
                    )
                })?,
                Some(data.clone()),
            ),
            meerkat_core::types::ImageData::Blob { blob_id } => (
                meerkat_core::verify_stored_image_blob(
                    self.blob_store.as_ref(),
                    blob_id,
                    media_type,
                    meerkat_core::live_adapter::MAX_LIVE_IMAGE_BYTES,
                )
                .await
                .map_err(|error| {
                    realtime_user_content_blob_error(
                        "realtime blob reference failed bounded integrity validation",
                        error,
                    )
                })?,
                None,
            ),
        };
        Ok(Some(PreparedRealtimeUserContentBlob {
            pending: meerkat_core::PendingRealtimeUserContentBlob {
                idempotency_key: idempotency_key.clone(),
                item_id: item_id.clone(),
                previous_item_id: previous_item_id.clone(),
                content_index: *content_index,
                blob_id: verified.blob_ref.blob_id,
                media_type: verified.blob_ref.media_type,
            },
            inline_data,
        }))
    }

    async fn ensure_prepared_realtime_user_content_blob(
        &self,
        prepared: &PreparedRealtimeUserContentBlob,
    ) -> Result<(), SessionError> {
        let verified = if let Some(data) = prepared.inline_data.as_deref() {
            meerkat_core::ensure_stored_image_blob(
                self.blob_store.as_ref(),
                &prepared.pending.media_type,
                data,
                meerkat_core::live_adapter::MAX_LIVE_IMAGE_BYTES,
            )
            .await
        } else {
            meerkat_core::verify_stored_image_blob(
                self.blob_store.as_ref(),
                &prepared.pending.blob_id,
                &prepared.pending.media_type,
                meerkat_core::live_adapter::MAX_LIVE_IMAGE_BYTES,
            )
            .await
        }
        .map_err(|error| {
            realtime_user_content_blob_error(
                "realtime user-content blob was not durably verified",
                error,
            )
        })?;
        if verified.blob_ref.blob_id != prepared.pending.blob_id
            || verified.blob_ref.media_type != prepared.pending.media_type
        {
            return Err(realtime_user_content_blob_error(
                "realtime user-content blob verification changed staged identity",
                format!(
                    "expected {} {}, found {} {}",
                    prepared.pending.blob_id,
                    prepared.pending.media_type,
                    verified.blob_ref.blob_id,
                    verified.blob_ref.media_type
                ),
            ));
        }
        Ok(())
    }

    async fn reconcile_pending_realtime_user_content_blob(
        &self,
        id: &SessionId,
        current: &mut Session,
        request: Option<&PreparedRealtimeUserContentBlob>,
    ) -> Result<Option<meerkat_core::RealtimeTranscriptApplyOutcome>, SessionError> {
        let Some(pending) = current.pending_realtime_user_content_blob() else {
            return Ok(None);
        };
        let pending_blob_valid = match meerkat_core::verify_stored_image_blob(
            self.blob_store.as_ref(),
            &pending.blob_id,
            &pending.media_type,
            meerkat_core::live_adapter::MAX_LIVE_IMAGE_BYTES,
        )
        .await
        {
            Ok(_) => true,
            Err(error) if pending_blob_is_definitively_invalid(&error) => false,
            Err(error) => {
                return Err(realtime_user_content_blob_error(
                    "pending realtime user-content blob verification was inconclusive",
                    error,
                ));
            }
        };
        let request_anchor = request.map(|prepared| &prepared.pending);
        let disposition = current
            .resolve_pending_realtime_user_content_blob_recovery(request_anchor, pending_blob_valid)
            .map_err(|error| {
                realtime_user_content_blob_error(
                    "failed to resolve pending realtime user-content blob recovery",
                    error,
                )
            })?;
        use meerkat_core::generated::session_document::RealtimeUserContentBlobRecoveryDisposition;
        match disposition {
            RealtimeUserContentBlobRecoveryDisposition::NoPending => {
                Err(realtime_user_content_blob_error(
                    "pending realtime user-content blob disappeared during recovery",
                    "machine observed no pending anchor",
                ))
            }
            RealtimeUserContentBlobRecoveryDisposition::RetryExact => {
                let request = request.ok_or_else(|| {
                    realtime_user_content_blob_error(
                        "exact pending realtime user-content retry lacked caller bytes/reference",
                        "missing exact request",
                    )
                })?;
                self.ensure_prepared_realtime_user_content_blob(request)
                    .await?;
                let outcome = self
                    .commit_pending_realtime_user_content_blob(id, current, request)
                    .await?;
                self.ensure_prepared_realtime_user_content_blob(request)
                    .await?;
                Ok(Some(outcome))
            }
            RealtimeUserContentBlobRecoveryDisposition::CommitVerifiedBeforeCurrent => {
                let recovered = PreparedRealtimeUserContentBlob {
                    pending,
                    inline_data: None,
                };
                self.ensure_prepared_realtime_user_content_blob(&recovered)
                    .await?;
                let _ = self
                    .commit_pending_realtime_user_content_blob(id, current, &recovered)
                    .await?;
                self.ensure_prepared_realtime_user_content_blob(&recovered)
                    .await?;
                Ok(None)
            }
            RealtimeUserContentBlobRecoveryDisposition::ClearInvalidBeforeCurrent => {
                current
                    .clear_invalid_pending_realtime_user_content_blob(request_anchor)
                    .map_err(|error| {
                        realtime_user_content_blob_error(
                            "failed to clear invalid pending realtime user-content blob",
                            error,
                        )
                    })?;
                // Never delete the content-addressed object here: this slot
                // does not prove exclusive ownership of a realm-shared blob.
                self.persist_realtime_transcript_snapshot(id, current)
                    .await?;
                Ok(None)
            }
        }
    }

    async fn commit_pending_realtime_user_content_blob(
        &self,
        id: &SessionId,
        current: &mut Session,
        prepared: &PreparedRealtimeUserContentBlob,
    ) -> Result<meerkat_core::RealtimeTranscriptApplyOutcome, SessionError> {
        let outcome = current.append_realtime_transcript_event(prepared.pending.canonical_event());
        let committed_matches = matches!(
            outcome.user_content.as_ref(),
            Some(meerkat_core::RealtimeUserContentApplyOutcome::Committed(identity))
                if prepared.pending.matches_identity(identity)
        );
        if !committed_matches || current.pending_realtime_user_content_blob().is_some() {
            return Err(realtime_user_content_blob_error(
                "pending realtime user-content blob reducer commit failed closed",
                format!("unexpected reducer outcome {outcome:?}"),
            ));
        }
        // Crash point C: reducer state may exist in-memory, but no receipt is
        // returned until the final session authority snapshot is durable.
        self.persist_realtime_transcript_snapshot(id, current)
            .await?;
        Ok(outcome)
    }

    async fn persist_realtime_transcript_snapshot(
        &self,
        id: &SessionId,
        session: &Session,
    ) -> Result<(), SessionError> {
        self.inner
            .sync_session_from_durable_snapshot(id, session.clone())
            .await?;
        if let Err(error) = self.persist_full_session(id).await {
            let _ = self.discard_live_session_unfenced(id).await;
            return Err(error);
        }
        Ok(())
    }

    /// Create a new persistent session service.
    pub fn new(
        builder: B,
        max_sessions: usize,
        store: Arc<dyn SessionStore>,
        runtime_store: Arc<dyn RuntimeStore>,
        blob_store: Arc<dyn BlobStore>,
    ) -> Self {
        Self::new_with_capacities(builder, max_sessions, 0, store, runtime_store, blob_store)
    }

    /// Create a persistent session service.
    ///
    /// The archived-history capacity parameter is retained for API
    /// compatibility, but archived history now reloads from durable authority
    /// instead of a process-local cache.
    pub fn new_with_archived_history_capacity(
        builder: B,
        max_sessions: usize,
        _archived_history_capacity: usize,
        store: Arc<dyn SessionStore>,
        runtime_store: Arc<dyn RuntimeStore>,
        blob_store: Arc<dyn BlobStore>,
    ) -> Self {
        Self::new_with_capacities(builder, max_sessions, 0, store, runtime_store, blob_store)
    }

    /// Create a persistent session service with explicit active-session
    /// capacity. The archived-history capacity parameter is ignored because
    /// archived history is loaded from durable authority.
    pub fn new_with_capacities(
        builder: B,
        active_session_capacity: usize,
        _archived_history_capacity: usize,
        store: Arc<dyn SessionStore>,
        runtime_store: Arc<dyn RuntimeStore>,
        blob_store: Arc<dyn BlobStore>,
    ) -> Self {
        let incremental = store.as_incremental();
        Self {
            inner: Arc::new(EphemeralSessionService::new(
                builder,
                active_session_capacity,
            )),
            incremental,
            runtime_store,
            blob_store,
            event_store: None,
            projector: None,
            checkpointer_gates: Mutex::new(HashMap::new()),
            live_checkpointers: Mutex::new(HashMap::new()),
            recovery_gates: Mutex::new(HashMap::new()),
            rejected_run_compaction_aborted: std::sync::Mutex::new(HashSet::new()),
            turn_finalization_gates: Mutex::new(HashMap::new()),
            event_projection_faults: Arc::new(Mutex::new(HashMap::new())),
            event_projection_gates: Arc::new(Mutex::new(HashMap::new())),
            event_projection_drains: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Attach the append-only event log and derived file projector used by
    /// persistent sessions.
    ///
    /// Projection is best-effort derived state. Append/project failures are
    /// logged and do not fail the session turn; callers must continue to treat
    /// `SessionStore`/`RuntimeStore` as the source of truth, not the projected
    /// JSONL files. The spawned projection tasks exit when their session event
    /// streams close, and create-time events without a correlated session id are
    /// discarded when the create-time stream closes.
    pub fn with_event_projection(
        mut self,
        event_store: Arc<dyn EventStore>,
        projector: Arc<SessionProjector>,
    ) -> Self {
        self.event_store = Some(event_store);
        self.projector = Some(projector);
        self
    }

    pub fn runtime_store(&self) -> Arc<dyn RuntimeStore> {
        self.runtime_store.clone()
    }

    /// Observe the exact committed runtime session authority without loading a
    /// Session document or falling back to SessionStore projection state.
    ///
    /// HeadCanonical backends are required to implement this as a small
    /// authority-row read. The RuntimeStore WholeBlob compatibility default is
    /// an exceptional verified document materialization, so hot observers
    /// should use it only when their profile/capability contract permits that
    /// cost. Either way, this wrapper never adds a second body read and refuses
    /// malformed/mismatched authority through the same typed boundary identity
    /// validator used by commit acknowledgement.
    pub async fn observe_persisted_session_authority(
        &self,
        id: &SessionId,
    ) -> Result<Option<RuntimeSessionAuthority>, SessionError> {
        let authority = self
            .runtime_store
            .load_session_boundary_authority(&Self::runtime_id_for_session(id))
            .await
            .map_err(|error| {
                SessionError::Agent(AgentError::InternalError(format!(
                    "failed to observe persisted runtime session authority for session {id}: {error}"
                )))
            })?;
        if let Some(authority) = authority.as_ref() {
            let _ = PreparedRuntimeBoundaryIdentity::from_runtime_authority(authority, id)?;
        }
        Ok(authority)
    }

    pub async fn persisted_runtime_state(
        &self,
        id: &SessionId,
    ) -> Result<Option<RuntimeState>, SessionError> {
        Self::load_runtime_state_for_session(&self.runtime_store, id).await
    }

    pub fn has_event_projection(&self) -> bool {
        self.event_store.is_some() && self.projector.is_some()
    }

    pub fn ensure_active_capacity_available(&self) -> Result<(), SessionError> {
        self.inner.ensure_active_capacity_available()
    }

    pub async fn reserve_create_session_admission(
        &self,
    ) -> Result<crate::ephemeral::RuntimeContextAdmissionGuard, SessionError> {
        self.inner.acquire_runtime_capacity_admission().await
    }

    pub async fn reserve_runtime_turn_admission(
        &self,
        id: &SessionId,
    ) -> Result<crate::ephemeral::RuntimeContextAdmissionGuard, SessionError> {
        match self.inner.join_active_runtime_context_admission(id).await {
            Ok(Some(admission)) => return Ok(admission),
            Ok(None) | Err(SessionError::NotFound { .. }) => {}
            Err(error) => return Err(error),
        }

        let recovery_gate = self.recovery_gate_for_session(id).await;
        let _turn_guard = recovery_gate.lock().await;
        let _ = self.discard_stale_live_session_if_needed(id).await?;
        if let Some(session) = self.load_authoritative_session_base(id).await? {
            self.reject_if_archived_session(id, &session)
                .await
                .map_err(crate::control_error_into_session_error)?;
        }
        match self.inner.acquire_runtime_context_admission(id).await {
            Ok(admission) => Ok(admission),
            Err(SessionError::NotFound { .. }) => {
                if self.load_authoritative_session_base(id).await?.is_some() {
                    self.inner.acquire_runtime_capacity_admission().await
                } else {
                    Err(SessionError::NotFound { id: id.clone() })
                }
            }
            Err(error) => Err(error),
        }
    }

    pub async fn create_session_with_reserved_admission(
        &self,
        req: CreateSessionRequest,
        admission: crate::ephemeral::RuntimeContextAdmissionGuard,
    ) -> Result<RunResult, SessionError> {
        let actor_seed_authority = self.resolve_actor_session_seed_authority(&req).await?;
        self.create_session_with_admission(
            req,
            PersistentCreateAdmission {
                reserved_create_admission: Some(admission),
                actor_seed_authority,
                archived_resume_authorization: ArchivedResumeAuthorization::RejectArchived,
                turn_boundary_already_held: false,
                resume_preparation: None,
                actor_witness_slot: None,
            },
        )
        .await
    }

    async fn resolve_actor_session_seed_authority(
        &self,
        req: &CreateSessionRequest,
    ) -> Result<ActorSessionSeedAuthority, SessionError> {
        let Some(session_id) = req
            .build
            .as_ref()
            .and_then(|build| build.resume_session.as_ref())
            .map(Session::id)
        else {
            return Ok(ActorSessionSeedAuthority::FreshGenerationZero);
        };
        let runtime_id = Self::runtime_id_for_session(session_id);
        let durable_authority_exists = match self.runtime_store.session_persistence_profile() {
            RuntimeSessionPersistenceProfile::WholeBlobV1 => self
                .runtime_store
                .load_whole_blob_store_authority(&runtime_id)
                .await
                .map_err(|error| {
                    SessionError::Agent(AgentError::InternalError(format!(
                        "failed to resolve WholeBlob actor seed authority for session {session_id}: {error}"
                    )))
                })?
                .is_some(),
            RuntimeSessionPersistenceProfile::HeadCanonicalV1 => self
                .runtime_store
                .load_session_boundary_authority(&runtime_id)
                .await
                .map_err(|error| {
                    SessionError::Agent(AgentError::InternalError(format!(
                        "failed to resolve HeadCanonical actor seed authority for session {session_id}: {error}"
                    )))
                })?
                .is_some(),
            profile => {
                return Err(SessionError::Agent(AgentError::InternalError(format!(
                    "unsupported runtime session persistence profile {profile} while resolving actor seed authority for session {session_id}"
                ))));
            }
        };
        Ok(if durable_authority_exists {
            ActorSessionSeedAuthority::DurableCommitted
        } else {
            ActorSessionSeedAuthority::FreshGenerationZero
        })
    }

    /// Classify and, when necessary, prepare one caller-supplied actor seed
    /// before the surface acquires the machine materialization fence.
    ///
    /// The returned value is owner-issued authority, not a hint. A fresh seed
    /// must cross actor creation without a committed-boundary receipt. A
    /// durable seed carries the complete bracketed resume result whose receipt
    /// the same service later consumes during actor insertion.
    #[doc(hidden)]
    pub async fn prepare_actor_session_seed(
        &self,
        req: &CreateSessionRequest,
    ) -> Result<PreparedActorSessionSeed, SessionError> {
        match self.resolve_actor_session_seed_authority(req).await? {
            ActorSessionSeedAuthority::FreshGenerationZero => {
                Ok(PreparedActorSessionSeed::FreshGenerationZero)
            }
            ActorSessionSeedAuthority::DurableCommitted => {
                let session_id = req
                    .build
                    .as_ref()
                    .and_then(|build| build.resume_session.as_ref())
                    .map(Session::id)
                    .ok_or_else(|| {
                        SessionError::Agent(AgentError::InternalError(
                            "durable actor seed authority omitted its session locator".to_string(),
                        ))
                    })?;
                Ok(PreparedActorSessionSeed::DurableCommitted {
                    resume: self.prepare_committed_boundary_resume(session_id).await?,
                })
            }
        }
    }

    /// Materialize a machine-prepared session after resolving whether the
    /// store already owns committed session authority for its exact id.
    ///
    /// Machine preparation may either create generation-zero runtime
    /// authority or recover a durable session in a new process. The surface
    /// cannot distinguish those cases from control flow alone, so the
    /// persistence profile's own authority row decides whether the supplied
    /// Session is a fresh seed or only a locator for an exact committed load.
    #[doc(hidden)]
    pub async fn create_fresh_session_with_reserved_admission(
        &self,
        req: CreateSessionRequest,
        admission: crate::ephemeral::RuntimeContextAdmissionGuard,
    ) -> Result<RunResult, SessionError> {
        let actor_seed_authority = self.resolve_actor_session_seed_authority(&req).await?;
        self.create_session_with_admission(
            req,
            PersistentCreateAdmission {
                reserved_create_admission: Some(admission),
                actor_seed_authority,
                archived_resume_authorization: ArchivedResumeAuthorization::RejectArchived,
                turn_boundary_already_held: false,
                resume_preparation: None,
                actor_witness_slot: None,
            },
        )
        .await
    }

    /// Create a runtime-backed actor while publishing its exact registry
    /// witness into `actor_witness_slot` at the same completion boundary as
    /// actor insertion.  Prepared runtime cleanup handles retain this shared
    /// slot, so cancellation after actor construction can compare-and-remove
    /// the exact incarnation rather than a bare SessionId.
    pub async fn create_session_with_reserved_admission_and_actor_witness(
        &self,
        req: CreateSessionRequest,
        admission: crate::ephemeral::RuntimeContextAdmissionGuard,
        actor_witness_slot: &LiveSessionActorWitnessSlot,
    ) -> Result<RunResult, SessionError> {
        let actor_seed_authority = self.resolve_actor_session_seed_authority(&req).await?;
        self.create_session_with_admission(
            req,
            PersistentCreateAdmission {
                reserved_create_admission: Some(admission),
                actor_seed_authority,
                archived_resume_authorization: ArchivedResumeAuthorization::RejectArchived,
                turn_boundary_already_held: false,
                resume_preparation: None,
                actor_witness_slot: Some(actor_witness_slot),
            },
        )
        .await
    }

    /// Boundary-owned variant of
    /// [`Self::create_session_with_reserved_admission_and_actor_witness`].
    /// Shared host/runtime facades use this while retaining B across machine
    /// materialization and actor registry publication.
    #[doc(hidden)]
    pub async fn create_session_with_reserved_admission_and_actor_witness_under_runtime_turn_boundary(
        &self,
        req: CreateSessionRequest,
        admission: crate::ephemeral::RuntimeContextAdmissionGuard,
        resume_preparation: Option<CommittedBoundaryResumePreparationReceipt>,
        actor_witness_slot: &LiveSessionActorWitnessSlot,
    ) -> Result<RunResult, SessionError> {
        let actor_seed_authority = self.resolve_actor_session_seed_authority(&req).await?;
        match (actor_seed_authority, resume_preparation.as_ref()) {
            (ActorSessionSeedAuthority::DurableCommitted, None) => {
                let session_id = req
                    .build
                    .as_ref()
                    .and_then(|build| build.resume_session.as_ref())
                    .map(Session::id)
                    .ok_or_else(|| {
                        SessionError::Agent(AgentError::InternalError(
                            "durable actor resume omitted its session body".to_string(),
                        ))
                    })?;
                return Err(SessionError::Agent(AgentError::InternalError(format!(
                    "persistent actor resume for '{session_id}' omitted its owner-issued preparation receipt"
                ))));
            }
            (ActorSessionSeedAuthority::FreshGenerationZero, Some(_)) => {
                return Err(SessionError::Agent(AgentError::InternalError(
                    "fresh persistent actor materialization carried a resume preparation receipt"
                        .to_string(),
                )));
            }
            (ActorSessionSeedAuthority::DurableCommitted, Some(_))
            | (ActorSessionSeedAuthority::FreshGenerationZero, None) => {}
        }
        self.create_session_with_admission(
            req,
            PersistentCreateAdmission {
                reserved_create_admission: Some(admission),
                actor_seed_authority,
                archived_resume_authorization: ArchivedResumeAuthorization::RejectArchived,
                turn_boundary_already_held: true,
                resume_preparation,
                actor_witness_slot: Some(actor_witness_slot),
            },
        )
        .await
    }

