#[async_trait]
impl<B: SessionAgentBuilder + 'static> SessionServiceControlExt for PersistentSessionService<B> {
    async fn append_system_context(
        &self,
        id: &SessionId,
        req: AppendSystemContextRequest,
    ) -> Result<AppendSystemContextResult, SessionControlError> {
        let persistence_profile = self.runtime_store.session_persistence_profile();
        let _turn_finalization_guard = self.acquire_runtime_turn_finalization_guard(id).await;
        let _projection_guard = self.recovery_gate_for_session(id).await.lock_owned().await;
        let existing_gate = self.existing_gate_for_session(id).await;
        if let Some(gate) = existing_gate.as_ref() {
            let gate_guard = gate.cancelled.lock().await;
            if *gate_guard {
                return Err(SessionControlError::Session(SessionError::NotFound {
                    id: id.clone(),
                }));
            }
            drop(gate_guard);
        }

        if self.inner.has_live_session(id).await? {
            if self
                .session_archived_by_authority_with_terminal(id, None)
                .await
                .map_err(SessionControlError::Session)?
            {
                return Err(Self::archived_not_found(id));
            }
            let status = self
                .inner
                .append_system_message_control(id, req)
                .await
                .map_err(SessionControlError::Session)?;
            if status == meerkat_core::service::AppendSystemContextStatus::Duplicate {
                return Ok(AppendSystemContextResult { status });
            }
            let persist_result = match persistence_profile {
                RuntimeSessionPersistenceProfile::WholeBlobV1 => {
                    let session = self
                        .inner
                        .export_session(id)
                        .await
                        .map_err(SessionControlError::Session)?;
                    self.save_normalized_session(session)
                        .await
                        .map(|_| ())
                        .map_err(SessionControlError::Session)
                }
                RuntimeSessionPersistenceProfile::HeadCanonicalV1 => {
                    let prepared = self
                        .prepare_runtime_boundary(id, "System-message control append", None)
                        .await
                        .map_err(SessionControlError::Session)?;
                    self.commit_prepared_head_canonical_actor_boundary(
                        id,
                        "System-message control append",
                        prepared,
                    )
                    .await
                    .map(|_| ())
                    .map_err(SessionControlError::Session)
                }
                profile => Err(SessionControlError::Session(SessionError::Agent(
                    AgentError::InternalError(format!(
                        "unsupported runtime session persistence profile {profile} while appending System message for session {id}"
                    )),
                ))),
            };
            if let Err(error) = persist_result {
                let _ = self.discard_live_session_unfenced(id).await;
                return Err(error);
            }
            return Ok(AppendSystemContextResult { status });
        }

        let mut session = match self
            .load_persisted_session_for_control(id, "append_system_context")
            .await?
        {
            Some(session) => session,
            None => {
                self.checkpointer_gates.lock().await.remove(id);
                return Err(SessionControlError::Session(SessionError::NotFound {
                    id: id.clone(),
                }));
            }
        };
        self.reject_if_archived_session(id, &session).await?;
        let status = session
            .append_system_message_idempotent(
                req.content.render_text(),
                req.source,
                req.idempotency_key,
                meerkat_core::types::message_timestamp_now(),
            )
            .map_err(|error| {
                SessionControlError::Session(SessionError::Agent(AgentError::ConfigError(
                    error.to_string(),
                )))
            })?;
        if status == meerkat_core::service::AppendSystemContextStatus::Duplicate {
            return Ok(AppendSystemContextResult { status });
        }
        match persistence_profile {
            RuntimeSessionPersistenceProfile::WholeBlobV1 => {
                self.save_normalized_session(session)
                    .await
                    .map_err(SessionControlError::Session)?;
            }
            RuntimeSessionPersistenceProfile::HeadCanonicalV1 => {
                self.persist_detached_head_canonical_session(
                    session,
                    "store-only System-message control append",
                )
                .await
                .map_err(SessionControlError::Session)?;
            }
            profile => {
                return Err(SessionControlError::Session(SessionError::Agent(
                    AgentError::InternalError(format!(
                        "unsupported runtime session persistence profile {profile} while persisting system context for session {id}"
                    )),
                )));
            }
        }
        Ok(AppendSystemContextResult { status })
    }

    async fn stage_tool_results(
        &self,
        id: &SessionId,
        req: StageToolResultsRequest,
    ) -> Result<StageToolResultsResult, SessionError> {
        validate_tool_result_video(&req.results)?;
        let persistence_profile = self.runtime_store.session_persistence_profile();

        // Match every other live/durable writer: boundary -> recovery ->
        // checkpointer gate -> deferred-state lock. The previous
        // cancelled-gate -> recovery order inverted archive and could deadlock.
        let _turn_finalization_guard = self.acquire_runtime_turn_finalization_guard(id).await;
        let _projection_guard = self.recovery_gate_for_session(id).await.lock_owned().await;
        let existing_gate = self.existing_gate_for_session(id).await;
        if let Some(state_arc) = self.inner.deferred_turn_state(id).await {
            let created_gate = existing_gate.is_none();
            let gate = match existing_gate {
                Some(gate) => gate,
                None => self.gate_for_session(id).await,
            };
            let gate_guard = gate.cancelled.lock().await;
            if *gate_guard {
                return Err(SessionError::NotFound { id: id.clone() });
            }

            let accepted_at = meerkat_core::time_compat::SystemTime::now();
            let mut attempts = 0usize;
            loop {
                attempts += 1;
                let (accepted, snapshot_state, persisted_state) = {
                    let guard = match state_arc.lock() {
                        Ok(guard) => guard,
                        Err(poisoned) => {
                            tracing::warn!(
                                session_id = %id,
                                "deferred-turn state lock poisoned while snapshotting staged tool results"
                            );
                            poisoned.into_inner()
                        }
                    };
                    let snapshot_state = guard.clone();
                    let mut candidate = snapshot_state.clone();
                    let accepted = candidate
                        .try_stage_tool_results(req.results.clone(), accepted_at)
                        .map_err(|error| {
                            SessionError::Agent(AgentError::ConfigError(error.to_string()))
                        })?;
                    (accepted, snapshot_state, candidate)
                };

                if accepted == 0 {
                    let ingress = match persistence_profile {
                        RuntimeSessionPersistenceProfile::HeadCanonicalV1 => {
                            self.inner
                                .classify_callback_result_ingress(id, req.results.clone())
                                .await?
                        }
                        RuntimeSessionPersistenceProfile::WholeBlobV1 => {
                            let session = self
                                .load_authoritative_session_base(id)
                                .await?
                                .ok_or_else(|| SessionError::NotFound { id: id.clone() })?;
                            session.classify_callback_result_ingress(&req.results)?
                        }
                        profile => {
                            return Err(SessionError::Agent(AgentError::InternalError(format!(
                                "unsupported runtime session persistence profile {profile} while classifying staged tool results for session {id}"
                            ))));
                        }
                    };
                    let disposition = if matches!(
                        ingress,
                        meerkat_core::session::CallbackResultIngress::AlreadyApplied
                    ) {
                        StageToolResultsDisposition::AlreadyApplied
                    } else {
                        StageToolResultsDisposition::AlreadyStaged
                    };
                    drop(gate_guard);
                    return Ok(StageToolResultsResult {
                        accepted_result_count: accepted,
                        disposition,
                    });
                }

                match persistence_profile {
                    RuntimeSessionPersistenceProfile::HeadCanonicalV1 => {
                        if self
                            .session_archived_by_authority_with_terminal(id, None)
                            .await?
                        {
                            drop(gate_guard);
                            return Err(SessionError::NotFound { id: id.clone() });
                        }
                        if matches!(
                            self.inner
                                .classify_callback_result_ingress(id, req.results.clone())
                                .await?,
                            meerkat_core::session::CallbackResultIngress::AlreadyApplied
                        ) {
                            drop(gate_guard);
                            return Ok(StageToolResultsResult {
                                accepted_result_count: 0,
                                disposition: StageToolResultsDisposition::AlreadyApplied,
                            });
                        }
                        let persist_result = async {
                            let prepared = self
                                .prepare_runtime_boundary_with_deferred_override(
                                    id,
                                    "staged callback tool results",
                                    Some(persisted_state),
                                )
                                .await?;
                            self.commit_prepared_head_canonical_actor_boundary(
                                id,
                                "staged callback tool results",
                                prepared,
                            )
                            .await?;
                            Ok::<(), SessionError>(())
                        }
                        .await;
                        if let Err(error) = persist_result {
                            drop(gate_guard);
                            let _ = self.discard_live_session_unfenced(id).await;
                            return Err(error);
                        }
                    }
                    RuntimeSessionPersistenceProfile::WholeBlobV1 => {
                        let mut session = match self.load_authoritative_session_base(id).await? {
                            Some(session) => session,
                            None => {
                                if created_gate {
                                    drop(gate_guard);
                                    self.checkpointer_gates.lock().await.remove(id);
                                }
                                return Err(SessionError::Agent(
                                    meerkat_core::error::AgentError::InternalError(
                                        "runtime-backed live session is missing its last committed snapshot"
                                            .to_string(),
                                    ),
                                ));
                            }
                        };

                        self.reject_if_archived_session(id, &session)
                            .await
                            .map_err(crate::control_error_into_session_error)?;
                        if matches!(
                            session.classify_callback_result_ingress(&req.results)?,
                            meerkat_core::session::CallbackResultIngress::AlreadyApplied
                        ) {
                            drop(gate_guard);
                            return Ok(StageToolResultsResult {
                                accepted_result_count: 0,
                                disposition: StageToolResultsDisposition::AlreadyApplied,
                            });
                        }
                        write_deferred_turn_state(&mut session, persisted_state)
                            .map_err(crate::control_error_into_session_error)?;
                        self.save_normalized_session(session).await?;
                    }
                    profile => {
                        return Err(SessionError::Agent(AgentError::InternalError(format!(
                            "unsupported runtime session persistence profile {profile} while staging tool results for session {id}"
                        ))));
                    }
                }

                let commit_result = {
                    let mut guard = match state_arc.lock() {
                        Ok(guard) => guard,
                        Err(poisoned) => {
                            tracing::warn!(
                                session_id = %id,
                                "deferred-turn state lock poisoned while committing staged tool results"
                            );
                            poisoned.into_inner()
                        }
                    };
                    if *guard == snapshot_state {
                        Some(
                            guard
                                .try_stage_tool_results(req.results.clone(), accepted_at)
                                .map_err(|error| {
                                    SessionError::Agent(AgentError::ConfigError(error.to_string()))
                                })?,
                        )
                    } else {
                        None
                    }
                };

                if let Some(live_accepted) = commit_result {
                    debug_assert_eq!(live_accepted, accepted);
                    drop(gate_guard);
                    return Ok(StageToolResultsResult {
                        accepted_result_count: accepted,
                        disposition: StageToolResultsDisposition::Staged,
                    });
                }

                if attempts >= 8 {
                    tracing::warn!(
                        session_id = %id,
                        "deferred-turn state kept changing after durable tool-result staging; discarding live session to force authoritative reload"
                    );
                    drop(gate_guard);
                    let _ = self.discard_live_session_unfenced(id).await;
                    return Ok(StageToolResultsResult {
                        accepted_result_count: accepted,
                        disposition: StageToolResultsDisposition::Staged,
                    });
                }
            }
        }

        if let Some(gate) = existing_gate {
            let gate_guard = gate.cancelled.lock().await;
            if *gate_guard {
                return Err(SessionError::NotFound { id: id.clone() });
            }
            drop(gate_guard);
        }

        let mut session = match self
            .load_persisted_session_for_control(id, "stage_tool_results")
            .await?
        {
            Some(session) => session,
            None => {
                self.checkpointer_gates.lock().await.remove(id);
                return Err(SessionError::NotFound { id: id.clone() });
            }
        };
        self.reject_if_archived_session(id, &session)
            .await
            .map_err(crate::control_error_into_session_error)?;
        if matches!(
            session.classify_callback_result_ingress(&req.results)?,
            meerkat_core::session::CallbackResultIngress::AlreadyApplied
        ) {
            return Ok(StageToolResultsResult {
                accepted_result_count: 0,
                disposition: StageToolResultsDisposition::AlreadyApplied,
            });
        }
        let mut state = session.deferred_turn_state().unwrap_or_default();
        let accepted = state
            .try_stage_tool_results(req.results, meerkat_core::time_compat::SystemTime::now())
            .map_err(|error| SessionError::Agent(AgentError::ConfigError(error.to_string())))?;
        write_deferred_turn_state(&mut session, state)
            .map_err(crate::control_error_into_session_error)?;
        match persistence_profile {
            RuntimeSessionPersistenceProfile::WholeBlobV1 => {
                self.save_normalized_session(session).await?;
            }
            RuntimeSessionPersistenceProfile::HeadCanonicalV1 => {
                self.persist_detached_head_canonical_session(
                    session,
                    "store-only staged callback tool results",
                )
                .await?;
            }
            profile => {
                return Err(SessionError::Agent(AgentError::InternalError(format!(
                    "unsupported runtime session persistence profile {profile} while persisting staged tool results for session {id}"
                ))));
            }
        }
        Ok(StageToolResultsResult {
            accepted_result_count: accepted,
            disposition: if accepted == 0 {
                StageToolResultsDisposition::AlreadyStaged
            } else {
                StageToolResultsDisposition::Staged
            },
        })
    }
}

impl<B: SessionAgentBuilder + 'static> PersistentSessionService<B> {
    /// Get the event injector for a session, if available.
    pub async fn event_injector(
        &self,
        session_id: &SessionId,
    ) -> Option<std::sync::Arc<dyn meerkat_core::EventInjector>> {
        self.inner.event_injector(session_id).await
    }

    #[doc(hidden)]
    pub async fn interaction_event_injector(
        &self,
        session_id: &SessionId,
    ) -> Option<std::sync::Arc<dyn meerkat_core::event_injector::SubscribableInjector>> {
        self.inner.interaction_event_injector(session_id).await
    }

    /// Get the comms runtime for a session, if available.
    pub async fn comms_runtime(
        &self,
        session_id: &SessionId,
    ) -> Option<std::sync::Arc<dyn meerkat_core::agent::CommsRuntime>> {
        self.inner.comms_runtime(session_id).await
    }

    /// Wait for a session to be registered.
    pub async fn wait_session_registered(&self) {
        self.inner.wait_session_registered().await;
    }

    /// Shut down all sessions.
    pub async fn shutdown(&self) {
        self.inner.shutdown().await;
    }

    /// Cancel all active checkpointer gates.
    ///
    /// After this call, in-flight checkpoints that are past the gate check
    /// will complete their current save. Subsequent WholeBlob checkpoints are
    /// no-ops; a HeadCanonical checkpoint instead fails the live actor because
    /// its required physical projection cannot be silently omitted. Use this
    /// during `stop()` to prevent checkpoint writes from racing with external
    /// cleanup operations.
    pub async fn cancel_all_checkpointers(&self) {
        let gates = self.checkpointer_gates.lock().await;
        for gate in gates.values() {
            let mut cancelled = gate.cancelled.lock().await;
            *cancelled = true;
        }
    }

    /// Re-enable checkpointer gates for all tracked sessions.
    ///
    /// Call this during `resume()` after `cancel_all_checkpointers()` was
    /// used during stop. Gates that were removed by `archive()` are not
    /// affected.
    pub async fn rearm_all_checkpointers(&self) {
        let gates = self.checkpointer_gates.lock().await;
        for gate in gates.values() {
            let mut cancelled = gate.cancelled.lock().await;
            *cancelled = false;
        }
    }

    /// Subscribe to session-wide events from the live inner service.
    pub async fn subscribe_session_events(
        &self,
        id: &SessionId,
    ) -> Result<meerkat_core::comms::EventStream, meerkat_core::comms::StreamError> {
        self.inner.subscribe_session_events(id).await
    }

    /// Whether a live session still has its deferred first turn pending.
    pub async fn live_deferred_first_turn_pending(
        &self,
        id: &SessionId,
    ) -> Result<bool, SessionError> {
        let _turn_finalization_guard = self.acquire_runtime_turn_finalization_guard(id).await;
        self.live_deferred_first_turn_pending_under_runtime_turn_boundary(id)
            .await
    }

    /// Inspect the deferred-first-turn witness while the caller already owns
    /// the stable outer boundary. This is the runtime-loop-safe variant; it
    /// takes only the next inner lock so ordering remains B -> R.
    pub async fn live_deferred_first_turn_pending_under_runtime_turn_boundary(
        &self,
        id: &SessionId,
    ) -> Result<bool, SessionError> {
        let _recovery_guard = self.recovery_gate_for_session(id).await.lock_owned().await;
        let _ = self.discard_stale_live_session_if_needed(id).await?;
        let Some(state) = self.inner.deferred_turn_state(id).await else {
            return Ok(false);
        };
        let state = state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        Ok(matches!(
            state.first_turn_phase(),
            DeferredFirstTurnPhase::Pending
        ))
    }

    /// Load the authoritative durable session view.
    ///
    /// RuntimeStore is the singular session authority. Store-only rows are not
    /// exposed as runtime truth and runtime bodies are never merged with
    /// SessionStore metadata.
    pub async fn load_authoritative_session(
        &self,
        id: &SessionId,
    ) -> Result<Option<Session>, SessionError> {
        self.load_authoritative_session_base(id).await
    }

    /// Observe the exact committed RuntimeStore body without reconciling the
    /// EventStore rewrite audit.
    ///
    /// This is the read-only sibling of [`Self::load_authoritative_session`].
    /// Operational resume preparation uses the latter when it is authorized
    /// to append or finalize rewrite-audit evidence; status, identity, and
    /// revival observations use this seam and never write while reading.
    pub async fn observe_authoritative_session_body(
        &self,
        id: &SessionId,
    ) -> Result<Option<Session>, SessionError> {
        self.load_committed_runtime_session_for_body(id, "authoritative session observation")
            .await
    }

    /// Ask the RuntimeStore-owned recovery authority to resolve one durable
    /// boundary and translate its exact outcome to the operator vocabulary.
    ///
    /// This session shell supplies only stable identity. It never loads or
    /// classifies candidate bytes, mints a successor, or writes a projection;
    /// the store-owned recovery seam proves and atomically consumes the exact
    /// runtime authority plus physical-head evidence.
    pub async fn recover_committed_boundary(
        &self,
        id: &SessionId,
    ) -> Result<CommittedBoundaryRecovery, SessionError> {
        if self.inner.has_live_session(id).await? {
            return Err(SessionError::Busy { id: id.clone() });
        }
        let recovery_gate = self.recovery_gate_for_session(id).await;
        let _recovery_guard = recovery_gate.lock_owned().await;
        if self.inner.has_live_session(id).await? {
            return Err(SessionError::Busy { id: id.clone() });
        }
        if !self.session_known_to_archive_authority(id).await? {
            return Err(SessionError::NotFound { id: id.clone() });
        }

        match self.store_owned_durable_tail_recovery_outcome(id).await? {
            meerkat_runtime::recovery::DurableTailRecoveryOutcome::Committed {
                recovered, ..
            } => Ok(CommittedBoundaryRecovery::Recovered {
                message_count: recovered.messages().len(),
            }),
            meerkat_runtime::recovery::DurableTailRecoveryOutcome::AlreadyAligned { .. } => {
                Ok(CommittedBoundaryRecovery::AlreadyCommitted)
            }
            meerkat_runtime::recovery::DurableTailRecoveryOutcome::Held => {
                Ok(CommittedBoundaryRecovery::Unprovable {
                    reason: format!(
                        "the durable tail for session {id} was held intact: the RuntimeStore could not produce and atomically consume exact recovery evidence; every durable copy is retained for reconciliation"
                    ),
                })
            }
            meerkat_runtime::recovery::DurableTailRecoveryOutcome::Refused => {
                Ok(CommittedBoundaryRecovery::Unprovable {
                    reason: format!(
                        "the durable tail for session {id} was refused by machine authority because persisted runtime facts contradict or already supersede the candidate; every durable copy is retained for operator reconciliation"
                    ),
                })
            }
        }
    }

    /// Recover and materialize one persistent resume through the single
    /// session-owner pipeline.
    ///
    /// The body is accepted only between equal backend-atomic resume
    /// observations. A successful materialization returns a non-cloneable
    /// capability that the same service/store owner must later consume during
    /// actor creation; callers never reduce that proof to a boolean.
    pub async fn prepare_committed_boundary_resume(
        &self,
        id: &SessionId,
    ) -> Result<PreparedCommittedBoundaryResume, SessionError> {
        let recovery = match self.recover_committed_boundary(id).await {
            Ok(
                recovery @ (CommittedBoundaryRecovery::AlreadyCommitted
                | CommittedBoundaryRecovery::Recovered { .. }),
            ) => Some(recovery),
            Ok(CommittedBoundaryRecovery::Unprovable { reason }) => {
                let observation = self
                    .runtime_store
                    .load_session_resume_observation(&Self::runtime_id_for_session(id))
                    .await
                    .map_err(|error| {
                        SessionError::Agent(AgentError::InternalError(format!(
                            "failed to observe unprovable resume authority for session {id}: {error}"
                        )))
                    })?;
                return Ok(
                    PreparedCommittedBoundaryResume::CommittedBoundaryUnprovable {
                        observation,
                        reason,
                    },
                );
            }
            Err(SessionError::NotFound { .. }) => None,
            Err(error) => return Err(error),
        };

        if recovery.is_some() {
            // Preserve rewrite-audit replay/finalization after physical A/H
            // convergence, before the body bracket that mints the capability.
            let _ = self.load_authoritative_session(id).await?;
        }

        let runtime_id = Self::runtime_id_for_session(id);
        let before = self
            .runtime_store
            .load_session_resume_observation(&runtime_id)
            .await
            .map_err(|error| {
                SessionError::Agent(AgentError::InternalError(format!(
                    "failed to observe resume authority before materializing session {id}: {error}"
                )))
            })?;
        let session = self.observe_authoritative_session_body(id).await?;
        let observation = self
            .runtime_store
            .load_session_resume_observation(&runtime_id)
            .await
            .map_err(|error| {
                SessionError::Agent(AgentError::InternalError(format!(
                    "failed to observe resume authority after materializing session {id}: {error}"
                )))
            })?;
        if before != observation {
            return Ok(
                PreparedCommittedBoundaryResume::AuthorityChangedDuringMaterialization {
                    observation,
                },
            );
        }

        let Some(session) = session else {
            return Ok(PreparedCommittedBoundaryResume::Unavailable {
                unavailable: PreparedCommittedBoundaryResumeUnavailable::Absent,
                observation,
            });
        };
        let Some(recovery) = recovery else {
            // The body appeared only after the recovery owner proved absence.
            // Do not mint a prepared capability for evidence that did not pass
            // through committed-boundary recovery.
            return Ok(
                PreparedCommittedBoundaryResume::AuthorityChangedDuringMaterialization {
                    observation,
                },
            );
        };

        let runtime_state = match observation.lifecycle() {
            meerkat_runtime::store::MachineLifecycleObservation::Decoded { record, .. } => {
                record.runtime_state()
            }
            meerkat_runtime::store::MachineLifecycleObservation::Missing
            | meerkat_runtime::store::MachineLifecycleObservation::Malformed { .. }
            | meerkat_runtime::store::MachineLifecycleObservation::Unsupported { .. } => None,
        };
        let archived = observation
            .catalog_entry()
            .and_then(|entry| entry.lifecycle_terminal())
            .is_some_and(SessionLifecycleTerminal::is_archived)
            || matches!(
                runtime_state,
                Some(RuntimeState::Retired | RuntimeState::Destroyed)
            )
            || (runtime_state.is_none()
                && session
                    .lifecycle_terminal()
                    .is_some_and(SessionLifecycleTerminal::is_archived));
        let materialization = if !archived {
            PreparedCommittedBoundaryResumeMaterialization::Active
        } else if matches!(
            runtime_state,
            None | Some(RuntimeState::Idle | RuntimeState::Retired)
        ) {
            PreparedCommittedBoundaryResumeMaterialization::Revivable
        } else {
            return Ok(PreparedCommittedBoundaryResume::Unavailable {
                unavailable: PreparedCommittedBoundaryResumeUnavailable::ArchivedNotRevivable {
                    runtime_state,
                },
                observation,
            });
        };
        let preparation = CommittedBoundaryResumePreparationReceipt {
            session_id: id.clone(),
            observation: observation.clone(),
            runtime_store: Arc::clone(&self.runtime_store),
            recovery,
        };
        Ok(PreparedCommittedBoundaryResume::Materializable {
            session: Box::new(session),
            materialization,
            observation,
            preparation,
        })
    }

    /// Whether RuntimeStore owns any durable authority for `id`, without the
    /// normal authoritative-read visibility arbitration.
    ///
    /// Lifecycle disposal needs an ownership predicate, not a readable live
    /// session. A catalog entry or physical boundary establishes ownership,
    /// but a bare runtime registration does not: after body loss it is only
    /// executor residue that explicit disposal must be able to retire. A
    /// SessionStore-only row likewise never establishes archive authority.
    pub async fn session_known_to_archive_authority(
        &self,
        id: &SessionId,
    ) -> Result<bool, SessionError> {
        let runtime_id = Self::runtime_id_for_session(id);
        if self
            .runtime_store
            .load_runtime_session_catalog_entry(&runtime_id)
            .await
            .map_err(|error| {
                SessionError::Agent(AgentError::InternalError(format!(
                    "failed to load runtime session catalog for session {id}: {error}"
                )))
            })?
            .is_some()
        {
            return Ok(true);
        }
        Ok(self
            .runtime_store
            .load_session_boundary_authority(&runtime_id)
            .await
            .map_err(|error| {
                SessionError::Agent(AgentError::InternalError(format!(
                    "failed to load runtime session authority for session {id}: {error}"
                )))
            })?
            .is_some())
    }

    /// Load the authoritative durable session metadata view.
    ///
    /// RuntimeStore is the singular authority. WholeBlob reads the exact
    /// store-verified committed body; HeadCanonical projects directly from
    /// the small committed head and therefore does not materialize transcript
    /// rows. A SessionStore-only row is not a recovery source.
    pub async fn load_authoritative_session_metadata(
        &self,
        id: &SessionId,
    ) -> Result<Option<meerkat_core::PersistedSessionMetadataView>, SessionError> {
        let corrupt_metadata_error = |err: serde_json::Error| {
            durable_session_restore_error(id, "durable metadata failed typed restore", err)
        };
        let runtime_id = Self::runtime_id_for_session(id);
        let Some(authority) = self
            .runtime_store
            .load_session_boundary_authority(&runtime_id)
            .await
            .map_err(|error| {
                SessionError::Agent(AgentError::InternalError(format!(
                    "failed to load RuntimeStore metadata authority for session {id}: {error}"
                )))
            })?
        else {
            return Ok(None);
        };
        if authority.session_id() != id {
            return Err(SessionError::Agent(AgentError::InternalError(format!(
                "RuntimeStore metadata authority identifies session {}, not {id}",
                authority.session_id()
            ))));
        }
        match authority {
            RuntimeSessionAuthority::WholeBlob(_) => {
                let snapshot = self
                    .runtime_store
                    .load_committed_whole_blob_snapshot(&runtime_id)
                    .await
                    .map_err(|error| {
                        SessionError::Agent(AgentError::InternalError(format!(
                            "failed to load exact WholeBlob metadata authority for session {id}: {error}"
                        )))
                    })?
                    .ok_or_else(|| {
                        SessionError::Agent(AgentError::InternalError(format!(
                            "WholeBlob metadata authority disappeared for session {id}"
                        )))
                    })?;
                meerkat_core::PersistedSessionMetadataView::try_from_session(snapshot.session())
                    .map(Some)
                    .map_err(corrupt_metadata_error)
            }
            RuntimeSessionAuthority::HeadCanonical(authority) => {
                let metadata = authority
                    .boundary_head()
                    .materialized_metadata()
                    .map_err(|error| {
                        SessionError::Agent(AgentError::InternalError(format!(
                            "failed to materialize committed HeadCanonical metadata for session {id}: {error}"
                        )))
                    })?;
                meerkat_core::PersistedSessionMetadataView::try_from_metadata_map(
                    id.clone(),
                    &metadata,
                )
                .map(Some)
                .map_err(corrupt_metadata_error)
            }
        }
    }

    /// Persist the live session through the runtime store's selected
    /// representation.
    ///
    /// WholeBlob exports and normalizes one RuntimeStore-owned document.
    /// HeadCanonical prepares the actor-owned suffix/head carrier and atomically
    /// commits it without exporting or encoding the full Session.
    /// Returns the committed message count and transcript digest so callers can
    /// seed a checkpointer without a second actor round-trip.
    async fn persist_full_session(&self, id: &SessionId) -> Result<(usize, String), SessionError> {
        match self.runtime_store.session_persistence_profile() {
            RuntimeSessionPersistenceProfile::WholeBlobV1 => {
                let session = self.export_session_with_labels(id).await?;
                let persisted = self.save_normalized_session(session).await?;
                let message_count = persisted.messages().len();
                let revision = meerkat_core::transcript_messages_digest(persisted.messages())
                    .map_err(|err| {
                        SessionError::Agent(meerkat_core::error::AgentError::InternalError(
                            format!(
                                "failed to digest persisted transcript for checkpoint seed: {err}"
                            ),
                        ))
                    })?;
                Ok((message_count, revision))
            }
            RuntimeSessionPersistenceProfile::HeadCanonicalV1 => {
                let PreparedRuntimeBoundary {
                    committed,
                    identity: prepared_boundary,
                    conversation_digest,
                    message_count,
                } = self
                    .prepare_runtime_boundary(id, "direct live session persistence", None)
                    .await?;
                let result = self
                    .runtime_store
                    .commit_prepared_session_boundary(
                        &Self::runtime_id_for_session(id),
                        meerkat_runtime::PreparedRuntimeSessionCommit::snapshot_only(committed),
                    )
                    .await
                    .map_err(|error| {
                        SessionError::Agent(AgentError::InternalError(format!(
                            "head-canonical live session persistence failed for session {id}: {error}"
                        )))
                    })?;
                let committed_authority = result.authority().ok_or_else(|| {
                    SessionError::Agent(AgentError::InternalError(format!(
                        "head-canonical live session persistence committed no session authority for session {id}"
                    )))
                })?;
                let committed_boundary = PreparedRuntimeBoundaryIdentity::from_runtime_authority(
                    committed_authority,
                    id,
                )?;
                if committed_boundary != prepared_boundary {
                    return Err(SessionError::Agent(AgentError::InternalError(format!(
                        "head-canonical live session persistence returned different authority for session {id}"
                    ))));
                }
                self.acknowledge_head_canonical_runtime_boundary_after_commit(
                    id,
                    &committed_boundary,
                )
                .await?;
                Ok((message_count, conversation_digest))
            }
            profile => Err(SessionError::Agent(AgentError::InternalError(format!(
                "unsupported runtime session persistence profile {profile} for session {id}"
            )))),
        }
    }

    async fn persist_full_session_or_discard_live(
        &self,
        id: &SessionId,
    ) -> Result<String, SessionError> {
        match self.persist_full_session(id).await {
            Ok((_message_count, revision)) => Ok(revision),
            Err(error) => {
                match self.discard_live_session_unfenced(id).await {
                    Ok(()) | Err(SessionError::NotFound { .. }) => {}
                    Err(discard_error) => {
                        tracing::warn!(
                            session_id = %id,
                            error = %discard_error,
                            "failed to discard live session after full-session persistence failure"
                        );
                    }
                }
                Err(error)
            }
        }
    }
}

