    #[tokio::test]
    async fn whole_blob_ordinary_acknowledgement_reads_only_bounded_store_authority() {
        let session = Session::new();
        let session_id = session.id().clone();
        let runtime_id = LogicalRuntimeId::for_session(&session_id);
        let artifact = session
            .to_persisted_artifact()
            .expect("encode test WholeBlob once");
        let probe = Arc::new(WholeBlobAuthorityReadProbe {
            inner: InMemoryRuntimeStore::new(),
            bounded_authority_reads: AtomicUsize::new(0),
            full_snapshot_reads: AtomicUsize::new(0),
        });
        probe
            .inner
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: artifact.bytes_arc(),
                },
            )
            .await
            .expect("seed exact committed WholeBlob row");
        let authority = probe
            .inner
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .expect("load seeded authority")
            .expect("seeded authority exists");
        let runtime_store: Arc<dyn RuntimeStore> = Arc::clone(&probe) as Arc<dyn RuntimeStore>;
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );

        service
            .acknowledge_whole_blob_runtime_session_boundary_under_runtime_turn_boundary(
                &session_id,
                authority.store_revision(),
                authority.blob_sha256(),
            )
            .await
            .expect("exact authority acknowledgement succeeds");

        assert_eq!(
            probe.bounded_authority_reads.load(Ordering::SeqCst),
            1,
            "ordinary acknowledgement must make one bounded authority read"
        );
        assert_eq!(
            probe.full_snapshot_reads.load(Ordering::SeqCst),
            0,
            "ordinary acknowledgement must not reload/hash/decode the WholeBlob body"
        );
    }

