    #[tokio::test]
    async fn boundary_and_rewrite_snapshot_writes_are_single_document_sized() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let counting = Arc::new(CountingRuntimeStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::clone(&counting) as Arc<dyn RuntimeStore>;
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let session_id = created.session_id;
        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "hello").await;

        // One committed turn = exactly one snapshot-carrying atomic boundary
        // apply, whose payload is one whole serialized document, and NO
        // additional whole-document snapshot commits on the side.
        counting.reset();
        let encode_before = meerkat_core::global_session_encode_bytes();
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "follow up").await;
        let boundary_doc = runtime_store
            .load_session_snapshot(&runtime_id)
            .await
            .expect("boundary snapshot should load")
            .expect("boundary snapshot should exist");
        assert_eq!(
            counting.boundary_apply_snapshots.load(Ordering::Acquire),
            1,
            "one committed turn must carry exactly one boundary snapshot"
        );
        assert_eq!(
            counting.boundary_apply_bytes.load(Ordering::Acquire),
            boundary_doc.len() as u64,
            "the boundary snapshot payload must be exactly one whole document"
        );
        assert_eq!(
            counting.snapshot_commits.load(Ordering::Acquire),
            0,
            "a committed turn must not add side-channel whole-document snapshot commits"
        );
        assert_eq!(
            counting.rewrite_snapshot_commits.load(Ordering::Acquire),
            0,
            "a committed turn must not write rewrite snapshots"
        );
        println!(
            "boundary save: {} bytes to the runtime store, {} bytes encoded",
            boundary_doc.len(),
            meerkat_core::global_session_encode_bytes() - encode_before,
        );

        // One persisted rewrite commit = exactly one whole-document rewrite
        // snapshot (the chain loop must not duplicate the document per
        // commit: 2026-07-29 chain-persistence audit).
        let parent_revision = service
            .load_authoritative_session_base(&session_id)
            .await
            .expect("load runtime authority before rewrite")
            .expect("session exists")
            .transcript_revision()
            .expect("parent revision");
        counting.reset();
        let encode_before = meerkat_core::global_session_encode_bytes();
        let result = service
            .rewrite_session_transcript(
                &session_id,
                meerkat_core::SessionTranscriptRewriteRequest {
                    selection: TranscriptRewriteSelection::MessageRange { start: 1, end: 4 },
                    replacement: vec![Message::BlockAssistant(
                        meerkat_core::BlockAssistantMessage::new(
                            vec![meerkat_core::AssistantBlock::Text {
                                text: "compacted assistant trace".to_string(),
                                meta: None,
                            }],
                            StopReason::EndTurn,
                        ),
                    )],
                    reason: TranscriptRewriteReason::new("compaction"),
                    actor: Some("test".to_string()),
                    expected_parent_revision: Some(parent_revision),
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect("rewrite should commit");
        assert_ne!(result.revision, result.parent_revision);
        let rewrite_doc = runtime_store
            .load_session_snapshot(&runtime_id)
            .await
            .expect("rewrite snapshot should load")
            .expect("rewrite snapshot should exist");
        assert_eq!(
            counting.rewrite_snapshot_commits.load(Ordering::Acquire),
            1,
            "one persisted rewrite commit must write exactly one rewrite snapshot"
        );
        assert_eq!(
            counting.rewrite_snapshot_bytes.load(Ordering::Acquire),
            rewrite_doc.len() as u64,
            "the rewrite snapshot payload must be exactly one whole document"
        );
        assert_eq!(
            counting.snapshot_commits.load(Ordering::Acquire),
            0,
            "an anchored single-commit rewrite must not write bridge or post-rewrite snapshots"
        );
        assert_eq!(
            counting.boundary_apply_snapshots.load(Ordering::Acquire),
            0,
            "a rewrite must not masquerade as a boundary apply"
        );
        println!(
            "rewrite-chain save: {} bytes to the runtime store, {} bytes encoded",
            rewrite_doc.len(),
            meerkat_core::global_session_encode_bytes() - encode_before,
        );
    }

    #[tokio::test]
    async fn whole_blob_k32_rewrite_is_one_encode_cas_and_receipt() {
        const REWRITE_COUNT: usize = 32;

        let projection_store = Arc::new(CountingProjectionSessionStore::new());
        let store: Arc<dyn SessionStore> = Arc::clone(&projection_store) as Arc<dyn SessionStore>;
        let counting = Arc::new(CountingRuntimeStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::clone(&counting) as Arc<dyn RuntimeStore>;
        let recording_events = Arc::new(RecordingEventStore::default());
        let event_store: Arc<dyn EventStore> = Arc::clone(&recording_events) as Arc<dyn EventStore>;
        let projector_root = tempfile::tempdir().expect("projector tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store,
            Arc::new(SessionProjector::new(projector_root.path().join(".rkat"))),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let session_id = created.session_id;
        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "hello").await;

        let mut rewritten = service
            .load_authoritative_session_base(&session_id)
            .await
            .expect("load runtime authority before rewrite chain")
            .expect("session exists");
        let mut commits = Vec::with_capacity(REWRITE_COUNT);
        for index in 0..REWRITE_COUNT {
            let parent_revision = rewritten
                .transcript_revision()
                .expect("rewrite parent revision");
            let commit = rewritten
                .commit_transcript_rewrite(
                    TranscriptRewriteSelection::MessageRange { start: 1, end: 2 },
                    vec![Message::User(UserMessage::text(format!(
                        "compacted rewrite {index}"
                    )))],
                    TranscriptRewriteReason::new("k32 whole-blob acceptance"),
                    Some("test".to_string()),
                    Some(parent_revision),
                )
                .expect("rewrite occurrence should commit");
            commits.push(commit);
        }
        let rewritten = service
            .normalized_session_for_persistence(rewritten)
            .await
            .expect("rewrite chain should normalize");

        let (receipt_rows_before, body_rows_before) = {
            let events = recording_events.events.lock().await;
            let session_events = events.get(&session_id).map(Vec::as_slice).unwrap_or(&[]);
            (
                session_events
                    .iter()
                    .filter(|stored| {
                        matches!(
                            stored.event,
                            AgentEvent::TranscriptRewriteAuditReceiptCommitted { .. }
                        )
                    })
                    .count(),
                session_events
                    .iter()
                    .filter(|stored| {
                        matches!(stored.event, AgentEvent::TranscriptRewriteCommitted { .. })
                    })
                    .count(),
            )
        };
        counting.reset();
        projection_store.reset();
        let receipt_append_calls_before = recording_events
            .rewrite_append_calls
            .load(Ordering::Acquire);
        let persisted = service
            .persist_normalized_transcript_rewrite_chain(rewritten, &commits, false)
            .await
            .expect("k=32 rewrite chain should persist");
        let rewrite_doc = runtime_store
            .load_session_snapshot(&runtime_id)
            .await
            .expect("rewrite snapshot should load")
            .expect("rewrite snapshot should exist");
        let (receipt_rows_after, body_rows_after, receipt_commit_count) = {
            let events = recording_events.events.lock().await;
            let session_events = events
                .get(&session_id)
                .expect("rewrite receipt should create a session event row");
            let receipt_commit_count = session_events
                .iter()
                .find_map(|stored| match &stored.event {
                    AgentEvent::TranscriptRewriteAuditReceiptCommitted { receipt, .. } => {
                        Some(receipt.commits().len())
                    }
                    _ => None,
                })
                .expect("rewrite receipt should be present");
            (
                session_events
                    .iter()
                    .filter(|stored| {
                        matches!(
                            stored.event,
                            AgentEvent::TranscriptRewriteAuditReceiptCommitted { .. }
                        )
                    })
                    .count(),
                session_events
                    .iter()
                    .filter(|stored| {
                        matches!(stored.event, AgentEvent::TranscriptRewriteCommitted { .. })
                    })
                    .count(),
                receipt_commit_count,
            )
        };

        assert_eq!(
            counting.rewrite_snapshot_cas_calls.load(Ordering::Acquire),
            1,
            "one logical rewrite suffix must cross one RuntimeStore CAS"
        );
        assert_eq!(
            counting.rewrite_snapshot_commits.load(Ordering::Acquire),
            1,
            "one logical rewrite suffix must write one final RuntimeStore document"
        );
        assert_eq!(
            counting.rewrite_snapshot_bytes.load(Ordering::Acquire),
            rewrite_doc.len() as u64,
            "the only RuntimeStore rewrite payload must be the final document"
        );
        assert_eq!(
            projection_store
                .authoritative_projection_calls
                .load(Ordering::Acquire),
            0,
            "one logical rewrite suffix must not duplicate RuntimeStore authority into SessionStore"
        );
        assert_eq!(
            counting
                .rewrite_successor_encode_bytes
                .load(Ordering::Acquire),
            rewrite_doc.len() as u64,
            "the successor must be whole-document encoded exactly once"
        );
        assert_eq!(receipt_rows_after - receipt_rows_before, 1);
        assert_eq!(receipt_commit_count, REWRITE_COUNT);
        assert_eq!(
            recording_events
                .rewrite_append_calls
                .load(Ordering::Acquire)
                - receipt_append_calls_before,
            1,
            "one logical rewrite suffix must make one exact receipt append"
        );
        assert_eq!(
            body_rows_after - body_rows_before,
            0,
            "current writers must emit no full-body transcript rewrite rows"
        );

        counting.reset();
        projection_store.reset();
        let retry_receipt_rows_before = receipt_rows_after;
        let retry_receipt_calls_before = recording_events
            .rewrite_append_calls
            .load(Ordering::Acquire);
        let retried = service
            .persist_normalized_transcript_rewrite_chain(persisted, &commits, false)
            .await
            .expect("exact k=32 retry should heal idempotently");
        let retry_receipt_rows_after = recording_events
            .events
            .lock()
            .await
            .get(&session_id)
            .into_iter()
            .flatten()
            .filter(|stored| {
                matches!(
                    stored.event,
                    AgentEvent::TranscriptRewriteAuditReceiptCommitted { .. }
                )
            })
            .count();
        assert_eq!(retried.id(), &session_id);
        assert_eq!(
            counting.rewrite_snapshot_cas_calls.load(Ordering::Acquire),
            1,
            "exact healing still performs one authority check"
        );
        assert_eq!(
            counting.rewrite_snapshot_commits.load(Ordering::Acquire),
            0,
            "exact healing must not rewrite the RuntimeStore document"
        );
        assert_eq!(
            counting.rewrite_snapshot_bytes.load(Ordering::Acquire),
            0,
            "exact healing must cross no RuntimeStore document bytes"
        );
        assert_eq!(
            counting
                .rewrite_successor_encode_bytes
                .load(Ordering::Acquire),
            0,
            "exact healing must reuse the already-landed document bytes"
        );
        assert_eq!(
            projection_store
                .authoritative_projection_calls
                .load(Ordering::Acquire),
            0,
            "healing must not consult or rewrite a non-authoritative SessionStore projection"
        );
        assert_eq!(
            recording_events
                .rewrite_append_calls
                .load(Ordering::Acquire)
                - retry_receipt_calls_before,
            1,
            "exact healing must perform one receipt identity check"
        );
        assert_eq!(
            retry_receipt_rows_after, retry_receipt_rows_before,
            "exact receipt publication must replay rather than append"
        );
    }

