    #[tokio::test]
    async fn test_persistent_restore_current_revision_surfaces_noop_rewrite() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let session_id = created.session_id;
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "hello").await;
        let rewritten = service
            .rewrite_session_transcript(
                &session_id,
                meerkat_core::SessionTranscriptRewriteRequest {
                    selection: TranscriptRewriteSelection::MessageRange { start: 1, end: 2 },
                    replacement: vec![Message::BlockAssistant(
                        meerkat_core::BlockAssistantMessage::new(
                            vec![meerkat_core::AssistantBlock::Text {
                                text: "rewritten".to_string(),
                                meta: None,
                            }],
                            StopReason::EndTurn,
                        ),
                    )],
                    reason: TranscriptRewriteReason::new("correction"),
                    actor: None,
                    expected_parent_revision: None,
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect("rewrite should commit");

        // Ordinary appends after an audited rewrite intentionally keep the
        // graph at its audited endpoint and do not retain another full live
        // revision body.
        committed_content_turn(
            &service,
            runtime_store.as_ref(),
            &session_id,
            "after rewrite",
        )
        .await;
        let appended = service
            .load_authoritative_session(&session_id)
            .await
            .expect("load appended rewritten session")
            .expect("session exists");
        let appended_revision = appended
            .transcript_revision()
            .expect("appended live revision");
        let history = appended
            .validated_transcript_history_state()
            .expect("history state should decode")
            .expect("rewritten session should retain audited history");
        assert_eq!(history.head(), rewritten.revision);
        assert_ne!(history.head(), appended_revision);
        assert!(
            !history.contains_revision(&appended_revision),
            "ordinary append must not manufacture a retained full live body"
        );

        let current = service
            .read_transcript_revision(
                &session_id,
                SessionTranscriptRevisionQuery {
                    revision: "current".to_string(),
                    offset: 0,
                    limit: None,
                },
            )
            .await
            .expect("current revision should resolve from the live appended transcript");
        assert_eq!(current.revision, appended_revision);
        assert_eq!(current.message_count, appended.messages().len());
        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        let authority_before = runtime_store
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .expect("load store-owned authority before no-op restore")
            .expect("store-owned authority exists before no-op restore");

        let err = service
            .restore_session_transcript_revision(
                &session_id,
                SessionTranscriptRestoreRevisionRequest {
                    revision: "current".to_string(),
                    reason: TranscriptRewriteReason::new("restore"),
                    actor: None,
                    expected_parent_revision: None,
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect_err(
                "restoring an appended current head without a retained live body must surface the typed no-op rewrite",
            );
        assert!(
            err.to_string()
                .contains("does not change transcript revision"),
            "unexpected error: {err}"
        );

        let authority_after = runtime_store
            .load_whole_blob_store_authority(&runtime_id)
            .await
            .expect("load store-owned authority after no-op restore")
            .expect("store-owned authority exists after no-op restore");
        assert_eq!(
            authority_after, authority_before,
            "a no-op restore must not advance or replace WholeBlob store authority"
        );
    }

    #[tokio::test]
    async fn test_persistent_restore_current_on_pre_revision_session_surfaces_noop_rewrite() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        );

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let session_id = created.session_id;
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "hello").await;

        // Pre-revision sessions have no retained body for the implicit digest
        // head; the live messages ARE the head body, so restoring `current`
        // still resolves through the selector and surfaces the typed no-op.
        let err = service
            .restore_session_transcript_revision(
                &session_id,
                SessionTranscriptRestoreRevisionRequest {
                    revision: "current".to_string(),
                    reason: TranscriptRewriteReason::new("restore"),
                    actor: None,
                    expected_parent_revision: None,
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect_err("restoring the digest head must surface the typed no-op rewrite");
        assert!(
            err.to_string()
                .contains("does not change transcript revision"),
            "unexpected error: {err}"
        );
    }

