    #[tokio::test]
    async fn test_transcript_rewrite_tombstone_survives_cold_restore_and_blocks_blob_write() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let blob_store = Arc::new(MemoryBlobStore::new());
        let service = PersistentSessionService::new(
            CapabilityBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            blob_store.clone(),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create session");
        let image = |key: &str, item_id: &str, data: &str| {
            meerkat_core::RealtimeTranscriptEvent::UserContentFinal {
                idempotency_key: key.to_string(),
                item_id: item_id.to_string(),
                previous_item_id: None,
                content_index: 0,
                content: vec![ContentBlock::Image {
                    media_type: "image/png".to_string(),
                    data: ImageData::Inline {
                        data: data.to_string(),
                    },
                }],
            }
        };
        let data = "iVBORw0KGgo=";
        let blob_id = meerkat_core::blob::content_blob_id("image/png", data);
        assert!(matches!(
            service
                .append_realtime_transcript_event(
                    &created.session_id,
                    image("removed-key", "removed-item", data),
                )
                .await
                .expect("commit original image")
                .user_content,
            Some(meerkat_core::RealtimeUserContentApplyOutcome::Committed(_))
        ));
        let before = service
            .export_realtime_refresh_session_snapshot(&created.session_id)
            .await
            .expect("read parent");
        let parent_revision = before.transcript_revision().expect("parent revision");
        service
            .rewrite_session_transcript(
                &created.session_id,
                SessionTranscriptRewriteRequest {
                    selection: TranscriptRewriteSelection::MessageRange { start: 0, end: 1 },
                    replacement: vec![Message::User(UserMessage::text("image removed"))],
                    reason: TranscriptRewriteReason::new("remove-image"),
                    actor: None,
                    expected_parent_revision: Some(parent_revision),
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect("rewrite should commit tombstone");

        blob_store
            .delete(&blob_id)
            .await
            .expect("remove old blob to prove retry does not rewrite it");
        service
            .discard_live_session(&created.session_id)
            .await
            .expect("force cold restore path");
        drop(service);
        let recovery = PersistentSessionService::new(
            CapabilityBuilder,
            4,
            store,
            runtime_store,
            blob_store.clone(),
        );
        let resume_source = recovery
            .load_authoritative_session(&created.session_id)
            .await
            .expect("cold-load rewritten runtime authority")
            .expect("rewritten runtime authority remains present after restart");
        recovery
            .create_session(resume_request(resume_source))
            .await
            .expect("cold resume must materialize the rewritten runtime authority");
        let retry = recovery
            .append_realtime_transcript_event(
                &created.session_id,
                image("removed-key", "retry-item", data),
            )
            .await
            .expect("tombstoned retry is a typed rejection");
        assert!(matches!(
            retry.user_content,
            Some(meerkat_core::RealtimeUserContentApplyOutcome::RejectedConflict { .. })
        ));
        assert!(retry.materialized_messages.is_empty());
        assert!(matches!(
            blob_store.get(&blob_id).await,
            Err(meerkat_core::BlobStoreError::NotFound(_))
        ));

        let fresh = recovery
            .append_realtime_transcript_event(
                &created.session_id,
                image("fresh-key", "fresh-item", data),
            )
            .await
            .expect("new key should commit after rewrite");
        assert!(matches!(
            fresh.user_content,
            Some(meerkat_core::RealtimeUserContentApplyOutcome::Committed(_))
        ));
        let durable = recovery
            .export_realtime_refresh_session_snapshot(&created.session_id)
            .await
            .expect("rewritten durable session remains valid");
        assert_eq!(durable.realtime_user_content_identities().len(), 1);
        assert_eq!(durable.realtime_user_content_tombstones().len(), 1);
        assert_eq!(durable.messages().len(), 2);
    }

    #[tokio::test]
    async fn test_transcript_rewrite_retaining_image_preserves_exact_replay_after_cold_restore() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let blob_store = Arc::new(MemoryBlobStore::new());
        let service = PersistentSessionService::new(
            CapabilityBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            blob_store.clone(),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create session");
        let data = "iVBORw0KGgo=";
        let image = |item_id: &str| meerkat_core::RealtimeTranscriptEvent::UserContentFinal {
            idempotency_key: "retained-key".to_string(),
            item_id: item_id.to_string(),
            previous_item_id: None,
            content_index: 0,
            content: vec![ContentBlock::Image {
                media_type: "image/png".to_string(),
                data: ImageData::Inline {
                    data: data.to_string(),
                },
            }],
        };
        service
            .append_realtime_transcript_event(&created.session_id, image("canonical-item"))
            .await
            .expect("commit original image");
        let before = service
            .export_realtime_refresh_session_snapshot(&created.session_id)
            .await
            .expect("read parent");
        let parent_revision = before.transcript_revision().expect("parent revision");
        service
            .rewrite_session_transcript(
                &created.session_id,
                SessionTranscriptRewriteRequest {
                    selection: TranscriptRewriteSelection::MessageRange { start: 0, end: 1 },
                    replacement: vec![
                        before.messages()[0].clone(),
                        Message::User(UserMessage::text("neighbor changed")),
                    ],
                    reason: TranscriptRewriteReason::new("retain-image"),
                    actor: None,
                    expected_parent_revision: Some(parent_revision),
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect("rewrite retaining canonical image");
        service
            .discard_live_session(&created.session_id)
            .await
            .expect("force cold restore path");
        drop(service);
        let recovery =
            PersistentSessionService::new(CapabilityBuilder, 4, store, runtime_store, blob_store);
        let resume_source = recovery
            .load_authoritative_session(&created.session_id)
            .await
            .expect("cold-load rewritten runtime authority")
            .expect("rewritten runtime authority remains present after restart");
        recovery
            .create_session(resume_request(resume_source))
            .await
            .expect("cold resume must materialize the rewritten runtime authority");
        let replay = recovery
            .append_realtime_transcript_event(&created.session_id, image("ignored-retry-item"))
            .await
            .expect("exact retained retry");
        assert!(matches!(
            replay.user_content,
            Some(meerkat_core::RealtimeUserContentApplyOutcome::AlreadyCommitted(
                meerkat_core::RealtimeUserContentIdentity { ref item_id, .. }
            )) if item_id == "canonical-item"
        ));
        assert!(replay.materialized_messages.is_empty());
    }

    /// An authoritative load read and materialized EVERY transcript rewrite
    /// record in the append-only log, and each record carries two full
    /// transcript bodies, so resume cost grew as retained-revisions x
    /// transcript. A steady-state load folds nothing, so it must materialize
    /// nothing.
    ///
    /// Two deterministic measurements, because either alone permits a false
    /// green. Per-thread hashed bytes would stay flat even if every body were
    /// still JSON-parsed; exact rows returned by the store would stay flat if
    /// some other seam hashed the whole graph. Both are asserted, never the
    /// clock and never a process-global before/after counter.
    ///
    /// Wired to [`crate::event_store::FileEventStore`] because that is what
    /// production wires. A store that hands back typed `StoredEvent` clones
    /// runs neither the record decode nor the raw-row read, so it cannot
    /// observe either property — a green assertion over such a store would
    /// certify something the shipped path does not do.
    #[tokio::test]
    async fn test_authoritative_load_materializes_no_rewrite_record_bodies() {
        async fn load_cost(rewrites: usize) -> (u64, u64) {
            let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
            let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
            let dir = tempfile::tempdir().expect("temp dir");
            let event_store = Arc::new(ObservingEventStore::new(dir.path().join("events")));
            let service = PersistentSessionService::new(
                CapabilityBuilder,
                4,
                Arc::clone(&store),
                Arc::clone(&runtime_store),
                memory_blob_store(),
            )
            .with_event_projection(
                Arc::clone(&event_store) as Arc<dyn EventStore>,
                Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
            );
            let created = service
                .create_session(create_request("seed", InitialTurnPolicy::Defer))
                .await
                .expect("create session");

            // Generation 0 grows the transcript so a per-record proof is
            // measurable; the rest are resume-shaped `[0, 1)` refreshes over
            // it, which is the production shape that accumulates revisions.
            for generation in 0..=rewrites {
                let parent = service
                    .export_realtime_refresh_session_snapshot(&created.session_id)
                    .await
                    .expect("read rewrite parent");
                let parent_revision = parent.transcript_revision().expect("parent revision");
                let (selection, replacement) = if generation == 0 {
                    (
                        TranscriptRewriteSelection::MessageRange { start: 0, end: 0 },
                        (0..12)
                            .map(|index| Message::User(UserMessage::text(format!("turn {index}"))))
                            .collect(),
                    )
                } else {
                    (
                        TranscriptRewriteSelection::MessageRange { start: 0, end: 1 },
                        vec![Message::User(UserMessage::text(format!(
                            "system prompt generation {generation}"
                        )))],
                    )
                };
                service
                    .rewrite_session_transcript(
                        &created.session_id,
                        SessionTranscriptRewriteRequest {
                            selection,
                            replacement,
                            reason: TranscriptRewriteReason::new("adversarial-rewrite-chain"),
                            actor: None,
                            expected_parent_revision: Some(parent_revision),
                            running_behavior: TranscriptEditRunningBehavior::Reject,
                        },
                    )
                    .await
                    .expect("rewrite commits");
            }
            service
                .discard_live_session(&created.session_id)
                .await
                .expect("force the durable load path");
            service
                .load_authoritative_session_base(&created.session_id)
                .await
                .expect("warm the per-shape decode memo");

            // WholeBlob ingress necessarily decodes the one current document.
            // Keep that O(document) work outside this audit-tail probe: this
            // regression is specifically about work proportional to retained
            // rewrite bodies after the current graph has already been proved.
            let session = service
                .load_committed_runtime_session_for_body(
                    &created.session_id,
                    "rewrite-body materialization probe",
                )
                .await
                .expect("load current runtime authority")
                .expect("session remains present");
            session
                .validate_transcript_history_state()
                .expect("prove current compact graph before audit-tail measurement");
            event_store.reset();
            let hashed_before = meerkat_core::session_content_digest_bytes();
            let replay = service
                .apply_transcript_rewrite_replay(&created.session_id, Some(session))
                .await
                .expect("measured rewrite-audit replay");
            service
                .verify_transcript_rewrite_audit_events(
                    replay.session.as_ref().expect("session remains present"),
                    &replay,
                )
                .await
                .expect("measured rewrite-audit verification");
            let rows = event_store.raw_reads();
            assert!(
                rows.iter().all(|(scope, _)| *scope == 2),
                "steady-state load must use only a store-authorized tail: {rows:?}"
            );
            (
                meerkat_core::session_content_digest_bytes() - hashed_before,
                rows.into_iter().map(|(_, rows)| rows as u64).sum(),
            )
        }

        let (few_hashed, few_rows) = load_cost(2).await;
        let (many_hashed, many_rows) = load_cost(8).await;
        println!(
            "authoritative load: 2 rewrites hashed {few_hashed} B / returned {few_rows} body rows, \
             8 rewrites hashed {many_hashed} B / returned {many_rows} body rows"
        );
        // Zero, not a bound: a load that folds nothing decides coverage from
        // commit identity, and a commit is read without its record's two
        // transcript bodies. One body materialized here would be N of them on
        // a session with N retained rewrites, which is the defect.
        assert_eq!(
            (few_rows, many_rows),
            (0, 0),
            "a steady-state authoritative load folds no rewrite, so it must \
             receive no rewrite record body: 2 rewrites returned \
             {few_rows}, 8 returned {many_rows}"
        );
        // Equality, not a bound: the residual is the ONE live-transcript digest
        // the coverage decision needs, and the defect is precisely that the
        // residual used to carry a per-retained-revision term as well.
        assert_eq!(
            few_hashed, many_hashed,
            "a steady-state authoritative load must re-prove nothing the loaded \
             session already proves, so its hashed bytes cannot grow with the \
             retained revision count: 2 rewrites hashed {few_hashed} bytes, 8 \
             hashed {many_hashed}"
        );
    }

    // ---------------------------------------------------------------
    // Store-owned rewrite audit
    // ---------------------------------------------------------------

    /// A [`crate::event_store::FileEventStore`] that records whether each
    /// combined audit read returned a store-authorized delta or a full
    /// reconciliation, plus the number of exact rewrite rows returned.
    struct ObservingEventStore {
        inner: crate::event_store::FileEventStore,
        reads: std::sync::Mutex<Vec<(u64, usize)>>,
        raw_reads: std::sync::Mutex<Vec<(u64, usize)>>,
    }

    impl ObservingEventStore {
        fn new(root: std::path::PathBuf) -> Self {
            Self {
                inner: crate::event_store::FileEventStore::new(root),
                reads: std::sync::Mutex::new(Vec::new()),
                raw_reads: std::sync::Mutex::new(Vec::new()),
            }
        }

        fn reset(&self) {
            self.reads.lock().expect("reads lock").clear();
            self.raw_reads.lock().expect("raw reads lock").clear();
        }

        /// `(scope, rows)` for every combined audit read since reset: scope 2
        /// is an authorized tail and scope 1 is full reconciliation.
        fn raw_reads(&self) -> Vec<(u64, usize)> {
            self.raw_reads.lock().expect("raw reads lock").clone()
        }

        /// `(from_seq, rows)` for every typed read since the last reset.
        fn typed_reads(&self) -> Vec<(u64, usize)> {
            self.reads.lock().expect("reads lock").clone()
        }

        fn rows_read(&self) -> usize {
            self.raw_reads()
                .into_iter()
                .chain(self.typed_reads())
                .map(|(_, rows)| rows)
                .sum()
        }
    }

    #[async_trait::async_trait]
    impl EventStore for ObservingEventStore {
        async fn append_envelopes(
            &self,
            session_id: &SessionId,
            envelopes: &[meerkat_core::event::EventEnvelope<AgentEvent>],
        ) -> Result<u64, EventStoreError> {
            self.inner.append_envelopes(session_id, envelopes).await
        }

        async fn append_transcript_rewrite_receipt_exact(
            &self,
            session_id: &SessionId,
            receipt: &meerkat_core::TranscriptRewriteAuditReceiptBatch,
            final_assistant_text: Option<&str>,
        ) -> Result<crate::event_store::ExactTranscriptRewriteReceiptAppend, EventStoreError>
        {
            self.inner
                .append_transcript_rewrite_receipt_exact(session_id, receipt, final_assistant_text)
                .await
        }

        async fn append_interaction_terminal_exact(
            &self,
            session_id: &SessionId,
            interaction_id: meerkat_core::interaction::InteractionId,
            envelope: &meerkat_core::event::EventEnvelope<AgentEvent>,
        ) -> Result<ExactInteractionAppend, EventStoreError> {
            self.inner
                .append_interaction_terminal_exact(session_id, interaction_id, envelope)
                .await
        }

        async fn record_projection_halt(
            &self,
            session_id: &SessionId,
            reason: &str,
        ) -> Result<(), EventStoreError> {
            self.inner.record_projection_halt(session_id, reason).await
        }

        async fn projection_halt(
            &self,
            session_id: &SessionId,
        ) -> Result<Option<crate::event_store::EventProjectionHaltMarker>, EventStoreError>
        {
            self.inner.projection_halt(session_id).await
        }

        async fn read_from(
            &self,
            session_id: &SessionId,
            from_seq: u64,
        ) -> Result<Vec<StoredEvent>, EventStoreError> {
            let rows = self.inner.read_from(session_id, from_seq).await?;
            self.reads
                .lock()
                .expect("reads lock")
                .push((from_seq, rows.len()));
            Ok(rows)
        }

        async fn read_raw_from(
            &self,
            session_id: &SessionId,
            from_seq: u64,
        ) -> Result<Option<Vec<crate::event_store::RawStoredEvent>>, EventStoreError> {
            let rows = self.inner.read_raw_from(session_id, from_seq).await?;
            if let Some(rows) = rows.as_ref() {
                self.raw_reads
                    .lock()
                    .expect("raw reads lock")
                    .push((from_seq, rows.len()));
            }
            Ok(rows)
        }

        async fn read_transcript_rewrite_audit(
            &self,
            session_id: &SessionId,
            expectation: crate::event_store::TranscriptRewriteAuditExpectation<'_>,
        ) -> Result<Option<crate::event_store::TranscriptRewriteAuditRead>, EventStoreError>
        {
            let read = self
                .inner
                .read_transcript_rewrite_audit(session_id, expectation)
                .await?;
            if let Some(read) = read.as_ref() {
                let (scope, rows) = match read {
                    crate::event_store::TranscriptRewriteAuditRead::AuthorizedTail(rows) => {
                        (2, rows.rewrite_rows().len())
                    }
                    crate::event_store::TranscriptRewriteAuditRead::FullReconciliation(rows) => {
                        (1, rows.rewrite_rows().len())
                    }
                };
                self.raw_reads
                    .lock()
                    .expect("raw reads lock")
                    .push((scope, rows));
            }
            Ok(read)
        }

        async fn finalize_transcript_rewrite_audit(
            &self,
            receipt: &crate::event_store::TranscriptRewritePrefixReceipt,
        ) -> Result<(), EventStoreError> {
            self.inner.finalize_transcript_rewrite_audit(receipt).await
        }

        async fn read_from_bounded(
            &self,
            session_id: &SessionId,
            from_seq: u64,
            max_rows: usize,
        ) -> Result<Vec<StoredEvent>, EventStoreError> {
            self.inner
                .read_from_bounded(session_id, from_seq, max_rows)
                .await
        }

        async fn last_seq(&self, session_id: &SessionId) -> Result<u64, EventStoreError> {
            self.inner.last_seq(session_id).await
        }
    }

    /// A session with `rewrites` resume-shaped refreshes over a real transcript,
    /// wired to an [`ObservingEventStore`], discarded so loads take the durable
    /// path.
