    /// While the session is LIVE in-process, an out-of-band extending store
    /// row must not hijack the runtime authority: the live runtime owns
    /// truth and recommits past any transient snapshot lag. (The COLD-resume
    /// counterpart — where the extending head IS served — is pinned by
    /// `test_stale_prefix_runtime_snapshot_defers_to_extending_store_head`.)
    #[tokio::test]
    async fn test_live_authority_ignores_typed_intra_turn_store_successor() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            runtime_store,
            memory_blob_store(),
        );

        let result = service
            .create_session(create_request(
                "hello",
                meerkat_core::service::InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create_session should succeed");
        let runtime_authority = service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("authoritative load should succeed")
            .expect("runtime authority should exist");

        let store_projection = mutate_test_session(
            runtime_authority.clone(),
            "in-run provisional",
            |store_projection| {
                store_projection.push(Message::User(UserMessage::text(
                    "intra-turn store projection must not replace live authority".to_string(),
                )));
            },
        );
        store
            .save(&store_projection)
            .await
            .expect("test should seed a typed intra-turn store projection");

        let authoritative = service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("authoritative load should succeed")
            .expect("authoritative session should exist");
        assert_eq!(
            authoritative.messages().len(),
            runtime_authority.messages().len(),
            "an intra-turn session-store successor must not override a live runtime authority snapshot"
        );
    }

    #[tokio::test]
    async fn test_live_runtime_read_ignores_typed_store_projection_when_snapshot_load_misses() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(GatedSnapshotRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            runtime_store.clone(),
            memory_blob_store(),
        );

        let result = service
            .create_session(create_request_with_metadata(
                "hello",
                meerkat_core::service::InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create_session should succeed");
        let output = service
            .apply_runtime_turn(
                &result.session_id,
                RunId::new(),
                runtime_content_turn_request("live runtime truth"),
                RunApplyBoundary::Immediate,
                vec![],
            )
            .await
            .expect("machine-owned runtime turn should succeed");
        machine_commit_runtime_output(
            &service,
            runtime_store.as_ref(),
            &result.session_id,
            &output,
        )
        .await
        .expect("machine-owned runtime output should commit");
        let live = service
            .export_live_session(&result.session_id)
            .await
            .expect("live session should export");
        let runtime_authority = service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("runtime authority should load")
            .expect("runtime authority should exist");

        let store_projection = mutate_test_session(
            runtime_authority,
            "in-run provisional",
            |store_projection| {
                store_projection.push(Message::User(UserMessage::text(
                    "intra-turn compatibility row".to_string(),
                )));
                store_projection.set_metadata(
                    SESSION_LABELS_KEY,
                    serde_json::json!({
                        "source": "store-projection",
                    }),
                );
            },
        );
        store
            .save(&store_projection)
            .await
            .expect("test should seed a typed intra-turn store projection");

        runtime_store.hide_next_session_snapshot_loads(1);
        let view = service
            .read(&result.session_id)
            .await
            .expect("read should preserve live runtime truth");
        assert_eq!(
            view.state.message_count,
            live.messages().len(),
            "read() must not expose an intra-turn store row when live runtime truth exists"
        );
        assert!(
            view.state.labels.is_empty(),
            "read() must not expose store projection metadata when live runtime truth exists"
        );
        assert!(
            service
                .has_live_session(&result.session_id)
                .await
                .expect("status should succeed"),
            "status must not let a store projection evict a live runtime session"
        );

        let authoritative = service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("authoritative load should succeed")
            .expect("runtime authority should remain present");
        assert_eq!(
            authoritative.messages().len(),
            live.messages().len(),
            "the store projection must not replace durable runtime authority"
        );
    }

    #[tokio::test]
    async fn test_live_runtime_list_and_cold_resume_ignore_session_store_successor() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(GatedSnapshotRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            runtime_store.clone(),
            memory_blob_store(),
        );

        let result = service
            .create_session(create_request_with_metadata(
                "hello",
                meerkat_core::service::InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create_session should succeed");
        let output = service
            .apply_runtime_turn(
                &result.session_id,
                RunId::new(),
                runtime_content_turn_request("live runtime truth"),
                RunApplyBoundary::Immediate,
                vec![],
            )
            .await
            .expect("machine-owned runtime turn should succeed");
        machine_commit_runtime_output(
            &service,
            runtime_store.as_ref(),
            &result.session_id,
            &output,
        )
        .await
        .expect("machine-owned runtime output should commit");
        let live = service
            .export_live_session(&result.session_id)
            .await
            .expect("live session should export");
        let runtime_authority = service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("runtime authority should load")
            .expect("runtime authority should exist");

        let store_projection =
            mutate_test_session(runtime_authority, "run boundary", |store_projection| {
                store_projection.push(Message::User(UserMessage::text(
                    "intra-turn compatibility row".to_string(),
                )));
                store_projection.set_metadata(
                    SESSION_LABELS_KEY,
                    serde_json::json!({
                        "source": "store-projection",
                    }),
                );
            });
        store
            .save(&store_projection)
            .await
            .expect("test should seed an inert SessionStore successor");

        let listed = service
            .list(SessionQuery::default())
            .await
            .expect("list should succeed");
        let summary = listed
            .iter()
            .find(|summary| summary.session_id == result.session_id)
            .expect("list should include the live runtime-backed session");
        assert_eq!(
            summary.message_count,
            live.messages().len(),
            "list() must report live/runtime metadata instead of the committed store successor"
        );
        assert!(
            summary.labels.is_empty(),
            "list() must not expose labels from the committed store successor"
        );
        assert!(
            service
                .has_live_session(&result.session_id)
                .await
                .expect("status should succeed"),
            "status must remain live after list inspects stale raw projections"
        );

        service
            .discard_live_session(&result.session_id)
            .await
            .expect("test should evict the live handle before resume");
        let restarted = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            runtime_store,
            memory_blob_store(),
        );
        // COLD resume remains RuntimeStore-owned. The longer SessionStore row
        // is neither a discovery source nor an authority candidate.
        let resume_source = restarted
            .load_authoritative_session(&result.session_id)
            .await
            .expect("resume source should load")
            .expect("resume source should remain present");
        assert_eq!(
            resume_source.messages().len(),
            live.messages().len(),
            "cold resume must ignore the SessionStore-only extension"
        );
        assert!(
            !resume_source.metadata().contains_key(SESSION_LABELS_KEY),
            "cold resume must not import SessionStore-only labels"
        );
        restarted
            .create_session(resume_request(resume_source))
            .await
            .expect("resume from RuntimeStore authority must succeed");
        assert!(
            restarted
                .has_live_session(&result.session_id)
                .await
                .expect("status should succeed after resume"),
            "resume from RuntimeStore authority must materialize a live session"
        );
    }

    #[tokio::test]
    async fn steady_state_full_load_path_verification_cost_is_bounded_and_constant() {
        // Covers the FULL production read path (load_authoritative_session ->
        // load_authoritative_session_base -> released-0.8.10 probes ->
        // read-source arbitration), not just the arbitration helper: a
        // regression that re-hashes retained history on every probe trips
        // this.
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            runtime_store,
            memory_blob_store(),
        );

        let result = service
            .create_session(create_request(
                "hello",
                meerkat_core::service::InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create_session should succeed");
        service
            .discard_live_session(&result.session_id)
            .await
            .expect("evict the live session so loads use durable state");

        // Prime the durable read path.
        service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("first durable load succeeds")
            .expect("runtime authority exists");

        // Per-load verification cost is BOUNDED and CONSTANT.
        //
        // Live authority is store-issued; this counter measures the remaining
        // transcript digests needed to arbitrate the two distinct durable
        // documents read here (the committed runtime snapshot and the
        // SessionStore head). What must never regress is accumulation across
        // repeated loads or re-proving every retained rewrite.
        const DOCUMENTS_VERIFIED_PER_LOAD: u64 = 2;
        let digests_before = meerkat_core::session_content_digest_computations();
        for _ in 0..5 {
            service
                .load_authoritative_session(&result.session_id)
                .await
                .expect("steady-state durable load succeeds")
                .expect("runtime authority exists");
        }
        let first_window = meerkat_core::session_content_digest_computations() - digests_before;
        assert!(
            first_window <= 5 * DOCUMENTS_VERIFIED_PER_LOAD,
            "steady-state durable loads must verify at most one digest per distinct \
             document read ({DOCUMENTS_VERIFIED_PER_LOAD} per load): {first_window} \
             computations over 5 loads"
        );

        // Second identical window: the cost must not grow with repetition —
        // that is what would signal a cache/seal regression or per-load
        // accumulation.
        let second_before = meerkat_core::session_content_digest_computations();
        for _ in 0..5 {
            service
                .load_authoritative_session(&result.session_id)
                .await
                .expect("steady-state durable load succeeds")
                .expect("runtime authority exists");
        }
        let second_window = meerkat_core::session_content_digest_computations() - second_before;
        assert_eq!(
            second_window, first_window,
            "steady-state per-load verification cost must be constant across repeated \
             loads: {first_window} then {second_window}"
        );
    }

    #[tokio::test]
    async fn test_authoritative_load_ignores_session_store_metadata_projection() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            runtime_store,
            memory_blob_store(),
        );

        let result = service
            .create_session(create_request(
                "hello",
                meerkat_core::service::InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create_session should succeed");
        let runtime_authority = service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("authoritative load should succeed")
            .expect("runtime authority should exist");

        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        let mut raw_store_projection = runtime_authority.clone();
        raw_store_projection.set_metadata(
            SESSION_LABELS_KEY,
            serde_json::json!({
                "source": "raw-store",
            }),
        );
        store
            .save(&raw_store_projection)
            .await
            .expect("test should be able to write a stale raw projection");
        service
            .discard_live_session(&result.session_id)
            .await
            .expect("test should evict the live session so read/list use durable state");

        let authoritative = service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("RuntimeStore authority must remain readable")
            .expect("RuntimeStore authority must remain present");
        assert_eq!(authoritative.messages(), runtime_authority.messages());
        assert_ne!(
            authoritative.metadata().get(SESSION_LABELS_KEY),
            raw_store_projection.metadata().get(SESSION_LABELS_KEY),
            "SessionStore metadata must not contaminate RuntimeStore body authority"
        );

        let read = service
            .read(&result.session_id)
            .await
            .expect("read must use RuntimeStore body authority");
        assert_eq!(read.state.message_count, runtime_authority.messages().len());
        let listed = service
            .list(SessionQuery::default())
            .await
            .expect("list must use RuntimeStore catalog authority");
        assert!(
            listed
                .iter()
                .any(|summary| summary.session_id == result.session_id),
            "catalog listing must retain the RuntimeStore-owned session"
        );
    }

