    #[tokio::test]
    async fn test_runtime_backed_stage_tool_results_without_live_handle_updates_runtime_authority()
    {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            runtime_store.clone(),
            memory_blob_store(),
        );

        let result = service
            .create_session(create_request(
                "hello",
                meerkat_core::service::InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create_session should succeed");
        service
            .discard_live_session(&result.session_id)
            .await
            .expect("test should be able to discard the live session");

        let staged = service
            .stage_tool_results(
                &result.session_id,
                StageToolResultsRequest {
                    results: vec![ToolResult::new(
                        "tool-call-1".to_string(),
                        "callback result".to_string(),
                        false,
                    )],
                },
            )
            .await
            .expect("stage_tool_results should update runtime authority");
        assert_eq!(staged.accepted_result_count, 1);
        assert_eq!(staged.disposition, StageToolResultsDisposition::Staged);

        let authoritative = service
            .load_authoritative_session(&result.session_id)
            .await
            .expect("authoritative load should succeed")
            .expect("authoritative session should exist");
        let deferred = authoritative
            .deferred_turn_state()
            .expect("runtime authority should carry deferred-turn state");
        assert_eq!(deferred.pending_tool_results().len(), 1);
        assert_eq!(deferred.pending_tool_results()[0].results.len(), 1);

        assert!(
            store
                .load(&result.session_id)
                .await
                .expect("SessionStore probe should succeed")
                .is_none(),
            "staged results must remain listable through the RuntimeStore catalog without a duplicate SessionStore row"
        );

        let view = service
            .read(&result.session_id)
            .await
            .expect("read should use durable runtime truth after live discard");
        assert_eq!(view.state.message_count, authoritative.messages().len());
        assert!(
            !service
                .has_live_session(&result.session_id)
                .await
                .expect("status should succeed"),
            "status should not recreate a live handle"
        );
        let listed = service
            .list(SessionQuery::default())
            .await
            .expect("list should succeed");
        let summary = listed
            .iter()
            .find(|summary| summary.session_id == result.session_id)
            .expect("list should include persisted runtime-backed session");
        assert_eq!(summary.message_count, authoritative.messages().len());

        let restarted = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            runtime_store,
            memory_blob_store(),
        );
        let resume_source = restarted
            .load_authoritative_session(&result.session_id)
            .await
            .expect("resume source should load from runtime authority")
            .expect("runtime authority should remain present after restart");
        let resumed = restarted
            .create_session(resume_request(resume_source))
            .await
            .expect("resume should materialize the runtime-authoritative snapshot");
        assert_eq!(resumed.session_id, result.session_id);
        let resumed_live = restarted
            .export_live_session(&result.session_id)
            .await
            .expect("resumed live session should export");
        let resumed_deferred = resumed_live
            .deferred_turn_state()
            .expect("resumed session should preserve staged tool results");
        assert_eq!(resumed_deferred.pending_tool_results().len(), 1);

        let before_redelivery = serde_json::to_value(
            restarted
                .load_authoritative_session(&result.session_id)
                .await
                .expect("authoritative replay load should succeed")
                .expect("authoritative replay session should exist"),
        )
        .expect("serialize replayed authoritative session");
        let duplicate = restarted
            .stage_tool_results(
                &result.session_id,
                StageToolResultsRequest {
                    results: vec![ToolResult::new(
                        "tool-call-1".to_string(),
                        "callback result".to_string(),
                        false,
                    )],
                },
            )
            .await
            .expect("identical persistent redelivery should coalesce");
        assert_eq!(duplicate.accepted_result_count, 0);
        assert_eq!(
            duplicate.disposition,
            StageToolResultsDisposition::AlreadyStaged,
            "a crash after durable stage but before run must remain a runnable continuation"
        );
        assert_eq!(
            serde_json::to_value(
                restarted
                    .load_authoritative_session(&result.session_id)
                    .await
                    .expect("authoritative duplicate load should succeed")
                    .expect("authoritative duplicate session should exist"),
            )
            .unwrap(),
            before_redelivery,
            "identical persistent redelivery must be a byte-noop"
        );

        for rejected in [
            ToolResult::new(
                "tool-call-1".to_string(),
                "conflicting callback result".to_string(),
                false,
            ),
            ToolResult::new(
                "wrong-tool-call".to_string(),
                "callback result".to_string(),
                false,
            ),
        ] {
            let error = restarted
                .stage_tool_results(
                    &result.session_id,
                    StageToolResultsRequest {
                        results: vec![rejected],
                    },
                )
                .await
                .expect_err("conflicting or wrong-id redelivery must fail typed");
            assert!(matches!(
                error,
                SessionError::Agent(AgentError::ConfigError(_))
            ));
            assert_eq!(
                serde_json::to_value(
                    restarted
                        .load_authoritative_session(&result.session_id)
                        .await
                        .expect("authoritative rejection load should succeed")
                        .expect("authoritative rejection session should exist"),
                )
                .unwrap(),
                before_redelivery,
                "rejected persistent redelivery must not poison the pending continuation"
            );
        }
    }

    #[tokio::test]
    async fn test_store_only_control_mutations_fail_closed_without_runtime_divergence() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        );
        let session = Session::new();
        let id = session.id().clone();
        store
            .save(&session)
            .await
            .expect("test should seed a store-only compatibility projection");

        let append_err = service
            .append_system_context(
                &id,
                AppendSystemContextRequest {
                    content: meerkat_core::lifecycle::run_primitive::CoreRenderable::text(
                        "store-only append must fail closed".to_string(),
                    ),
                    source: Some("api".to_string()),
                    idempotency_key: Some("store-only-append".to_string()),
                },
            )
            .await
            .expect_err("store-only projection must not be promoted by append");
        assert!(
            matches!(
                append_err,
                SessionControlError::Session(SessionError::NotFound { id: ref missing })
                    if missing == &id
            ),
            "append must treat missing RuntimeStore authority as NotFound: {append_err:?}"
        );

        let stage_err = service
            .stage_tool_results(
                &id,
                StageToolResultsRequest {
                    results: vec![ToolResult::new(
                        "tool-call-1".to_string(),
                        "callback result".to_string(),
                        false,
                    )],
                },
            )
            .await
            .expect_err("store-only projection must not be promoted by staged tool results");
        assert!(
            matches!(
                stage_err,
                SessionError::NotFound { id: ref missing } if missing == &id
            ),
            "stage must treat missing RuntimeStore authority as NotFound: {stage_err:?}"
        );

        let archive_err = service
            .archive(&id)
            .await
            .expect_err("runtime-backed archive must route through machine");
        assert!(
            matches!(
                archive_err,
                SessionError::Unsupported(ref message)
                    if message.contains("MachineSessionArchiveProtocol")
            ),
            "archive error should require machine authority: {archive_err:?}"
        );

        let raw = store
            .load(&id)
            .await
            .expect("raw store load should succeed")
            .expect("store-only projection should remain present");
        assert!(
            raw.messages().is_empty(),
            "append rejection must not mutate the store-only projection"
        );
        assert!(
            raw.deferred_turn_state().is_none(),
            "stage rejection must not mutate the store-only projection"
        );
        assert!(
            !session_marks_archived(&raw),
            "archive rejection must not persist archived lifecycle metadata"
        );
        assert!(
            runtime_store
                .load_session_snapshot(
                    &PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&id)
                )
                .await
                .expect("runtime snapshot load should succeed")
                .is_none(),
            "store-only control mutations must not create runtime authority"
        );
    }

    #[tokio::test]
    async fn test_machine_authorized_archive_accepts_never_run_session() {
        // A generation-zero RuntimeStore body is enough authority for a session
        // that never ran a turn. Archive must retire it without SessionStore.
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        );
        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create generation-zero RuntimeStore authority");
        let id = created.session_id;

        let machine = std::sync::Arc::new(meerkat_runtime::MeerkatMachine::persistent(
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        ));
        machine
            .register_session(id.clone())
            .await
            .expect("register the never-run session (the mob field shape)");

        service
            .archive_with_machine_protocol(
                &id,
                MachineSessionArchiveProtocol::from_machine(machine.as_ref()),
            )
            .await
            .expect("archiving a never-run session must succeed, not strand it");

        assert!(
            store
                .load(&id)
                .await
                .expect("SessionStore probe should succeed")
                .is_none(),
            "archive must not persist lifecycle metadata in SessionStore"
        );
        let runtime_state = meerkat_runtime::store::load_runtime_state(
            runtime_store.as_ref(),
            &PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&id),
        )
        .await
        .expect("runtime state load should succeed");
        assert_eq!(
            runtime_state,
            Some(meerkat_runtime::RuntimeState::Retired),
            "archive must durably retire the registered runtime session"
        );
    }

    #[tokio::test]
    async fn test_machine_archive_treats_retired_runtime_as_terminal_without_body_rewrite() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        );
        let session = Session::new();
        let id = session.id().clone();
        let runtime_id = PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&id);
        let session_bytes = serde_json::to_vec(&session).expect("serialize content body");
        runtime_store
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: session_bytes.clone().into(),
                },
            )
            .await
            .expect("seed RuntimeStore content body");

        let machine = meerkat_runtime::MeerkatMachine::persistent(
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        );
        machine
            .register_session(id.clone())
            .await
            .expect("register active runtime");
        meerkat_runtime::RuntimeControlPlane::retire(&machine, &runtime_id)
            .await
            .expect("seed retired RuntimeStore lifecycle");

        assert!(
            service
                .session_archived_by_authority(&id, &session)
                .await
                .expect("public archive projection"),
            "public reads must derive archived state from RuntimeStore lifecycle"
        );
        let duplicate = service
            .archive_with_machine_protocol(
                &id,
                MachineSessionArchiveProtocol::from_machine(&machine),
            )
            .await;
        assert!(
            matches!(duplicate, Err(SessionError::NotFound { .. })),
            "duplicate archive over Retired must keep the public NotFound contract: {duplicate:?}"
        );

        let retained = runtime_store
            .load_session_snapshot(&runtime_id)
            .await
            .expect("load retained RuntimeStore body")
            .expect("RuntimeStore body remains durable");
        assert_eq!(
            retained.as_slice(),
            session_bytes.as_slice(),
            "duplicate archive must not rewrite the content body"
        );
        assert!(
            store
                .load(&id)
                .await
                .expect("SessionStore probe should succeed")
                .is_none(),
            "duplicate archive must not mint SessionStore state"
        );
    }

    #[tokio::test]
    async fn test_archive_ownership_requires_catalog_or_physical_boundary() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store = Arc::new(InMemoryRuntimeStore::new());
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        );
        let session = Session::new();
        let id = session.id().clone();
        let runtime_id = PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&id);
        runtime_store
            .commit_session_snapshot(
                &runtime_id,
                SerializedSessionSnapshot {
                    session_snapshot: serde_json::to_vec(&session)
                        .expect("serialize session body")
                        .into(),
                },
            )
            .await
            .expect("seed exact session body and catalog");
        let machine = meerkat_runtime::MeerkatMachine::persistent(
            Arc::clone(&runtime_store) as Arc<dyn RuntimeStore>,
            memory_blob_store(),
        );
        machine
            .register_session(id.clone())
            .await
            .expect("register runtime lifecycle");
        meerkat_runtime::RuntimeControlPlane::retire(&machine, &runtime_id)
            .await
            .expect("retire runtime lifecycle");

        assert!(
            service
                .session_known_to_archive_authority(&id)
                .await
                .expect("observe body-backed archive ownership"),
            "a real RuntimeStore body/catalog boundary must remain protected as archive-owned"
        );

        runtime_store
            .clear_session_snapshot(&runtime_id)
            .await
            .expect("remove body, catalog, and physical boundary");
        assert_eq!(
            meerkat_runtime::store::load_runtime_state(runtime_store.as_ref(), &runtime_id)
                .await
                .expect("load retained runtime lifecycle"),
            Some(RuntimeState::Retired),
            "fixture must retain bare lifecycle residue"
        );
        assert!(
            !service
                .session_known_to_archive_authority(&id)
                .await
                .expect("observe bodyless archive ownership"),
            "a bare runtime lifecycle registration must not resurrect durable archive ownership"
        );
    }

